/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A57 frozen manifest; 20-lemma checkpoints are validated before publication. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});
D('introspection',{etymology:E('Introspection combines intro- “inward” and spect, from Latin specere “to look”; it means examining one’s own thoughts and motives.','introspection'),contexts:[C('introspection.s1','心理反思','After the interview, Maya’s introspection helped her see that she had answered too quickly when asked about teamwork.','面试后，玛雅通过反省意识到，谈到团队合作时自己回答得太快了。','After the interview / Maya’s introspection helped her see / that she had answered too quickly / when asked about teamwork.','introspection 是名词，指向内审视自己的思想、动机或行为。','她复盘自己的回答方式，体现了自我反思。')],mistakes:[M('The coach praised Leo’s introspection because he examined only the other candidates and never considered his own choices.','The coach praised Leo’s introspection because he examined his own choices and reactions.','只观察别人而不审视自己，不符合 introspection 的含义。')],quiz:[Q('introspection',1,1,'What does introspection focus on?','one’s own thoughts and motives','the weather outside','another person’s travel plans','one’s own thoughts and motives','introspection 指对自身内心的审视。'),Q('introspection',2,1,'Which action is introspection?','reviewing why you reacted angrily','counting cars on a street','copying a colleague’s report','reviewing why you reacted angrily','分析自己生气的原因是在反思自身。'),Q('introspection',3,1,'Introspection is a?','noun for self-examination','verb meaning to interrupt','adjective meaning intuitive','noun for self-examination','introspection 是表示自我审视的名词。','word-formation'),Q('introspection',4,1,'A period of introspection is likely to involve?','careful thought about one’s own behavior','an inspection of someone else’s luggage','a public vote','careful thought about one’s own behavior','反思通常考察自己的行为与想法。')]});
D('introspective',{etymology:E('Introspective is formed from introspect, “to examine inwardly,” with the adjective suffix -ive.','introspective'),contexts:[C('introspective.s1','人物描写','The introspective novelist kept a private notebook in which she questioned the motives behind each decision.','这位善于内省的小说家有一本私人笔记，常在其中追问每个决定背后的动机。','The introspective novelist kept a private notebook / in which she questioned / the motives behind each decision.','introspective 作形容词，描述倾向于审视自身思想和动机的人。','她持续审视自己的决定，表现出内省倾向。')],mistakes:[M('The profile called Arun introspective because he spent every meeting studying strangers’ faces but never considered his own feelings.','The profile called Arun introspective because he often examined his own feelings and motives.','只观察他人而不自我审视，不支持 introspective 这一描述。')],quiz:[Q('introspective',1,1,'An introspective person tends to?','examine their own thoughts','avoid thinking about themselves','study only mechanical devices','examine their own thoughts','introspective 描写善于内省的人。'),Q('introspective',2,1,'Which person is most introspective?','one who reflects on why she made a choice','one who memorizes every street name','one who refuses to consider any motive','one who reflects on why she made a choice','她反思自己的选择，体现内省。'),Q('introspective',3,1,'Choose the correct form: “Her ___ writing explores private doubts.”','introspective','introspection','introspectively','introspective','空格修饰 writing，需要形容词 introspective。','word-formation'),Q('introspective',4,1,'Introspective is closest in meaning to?','self-reflective','outgoing','careless','self-reflective','self-reflective 同样表示自我反思的。','confusable')]});
D('introvert',{etymology:E('Introvert combines intro- “inward” with vert, from Latin vertere “to turn”; the noun names a person who tends to focus inward, and the verb means turn inward.','introvert'),contexts:[C('introvert.s1','性格描述','As an introvert, Nia enjoys the book club but needs a quiet evening afterward to recharge.','作为性格内向的人，妮娅喜欢读书会，但之后需要一个安静的晚上恢复精力。','As an introvert / Nia enjoys the book club / but needs a quiet evening afterward / to recharge.','introvert 作名词指更偏好安静或小范围社交的人，不等于不友善。','妮娅喜欢活动，也需要独处恢复精力，体现内向倾向。')],mistakes:[M('The counselor called Sam an introvert solely because he was rude and disliked every person he met.','The counselor called Sam an introvert because he preferred quiet time after large gatherings.','内向指社交偏好，不等于粗鲁或讨厌所有人。')],quiz:[Q('introvert',1,1,'An introvert often prefers?','quiet reflection or smaller social settings','constant attention from a huge crowd','avoiding every human relationship','quiet reflection or smaller social settings','introvert 常偏好安静或小范围社交。'),Q('introvert',2,1,'Which statement about an introvert is sound?','being introverted does not by itself mean being unfriendly','every introvert dislikes all people','an introvert cannot enjoy a meeting','being introverted does not by itself mean being unfriendly','内向与是否友善不是同一判断。','distinction'),Q('introvert',3,2,'To introvert one’s attention is to turn it?','inward','into a legal contract','toward the ceiling only','inward','动词 introvert 可表示使注意力转向内心。'),Q('introvert',4,1,'“She is an introvert” uses introvert as a?','noun for a person','past-tense verb','plural adjective','noun for a person','此处 introvert 作名词。','word-formation')]});
D('intruder',{etymology:E('Intruder is formed from intrude, from Latin intrudere “to thrust in,” with the agent suffix -er.','intruder'),contexts:[C('intruder.s1','住宅安防','The motion sensor alerted the guard when an intruder entered the locked archive after hours.','一名闯入者在闭馆后进入上锁的档案室时，动作传感器向保安发出了警报。','The motion sensor alerted the guard / when an intruder entered the locked archive / after hours.','intruder.s1 指未经许可进入某处的人。','档案室上锁且已闭馆，进入者没有许可。')],mistakes:[M('The museum labeled the invited curator an intruder even though she had a key and was scheduled to enter.','The museum labeled the person who forced entry after closing an intruder.','获准按安排进入的人不是 intruder。')],quiz:[Q('intruder',1,1,'An intruder enters a place?','without permission','as an invited speaker','only after receiving a key','without permission','intruder 指未经许可闯入的人。'),Q('intruder',2,2,'A nonhuman intruder in a system might be?','an organism disrupting the system','a scheduled maintenance worker','a harmless label on a box','an organism disrupting the system','intruder.s2 也可指侵入并干扰系统的生物或事物。'),Q('intruder',3,1,'Which person is an intruder?','someone who breaks into a closed office','a visitor welcomed by the receptionist','an employee entering with authorization','someone who breaks into a closed office','擅自闯入关闭的办公室符合 intruder。'),Q('intruder',4,1,'Intruder is related to which verb?','intrude','intuit','introduce','intrude','intruder 由 intrude 加表示人的 -er 构成。','word-formation')]});
D('intrusion',{etymology:E('Intrusion is formed from intrude with -sion and names an unwelcome entry or interference.','intrusion'),contexts:[C('intrusion.s1','隐私保护','She considered the repeated calls during her medical appointment an intrusion on her privacy.','她认为自己看诊时接连不断的电话侵犯了她的隐私。','She considered the repeated calls / during her medical appointment / an intrusion on her privacy.','intrusion 指未经允许的进入或对私人空间、活动的打扰。','私人就诊期间反复来电构成对隐私的打扰。')],mistakes:[M('The tenant called the landlord’s announced, scheduled inspection an intrusion even though the tenant had agreed to the visit.','The tenant called the landlord’s unannounced entry into the bedroom an intrusion.','已协商同意的检查并非未经许可的侵扰。')],quiz:[Q('intrusion',1,1,'An intrusion is often?','an unwelcome entry or interference','a helpful invitation','a scheduled celebration','an unwelcome entry or interference','intrusion 常指不受欢迎的闯入或干扰。'),Q('intrusion',2,1,'Which is an intrusion on privacy?','reading someone’s private messages without permission','asking whether a person is free to talk','sending an agreed appointment reminder','reading someone’s private messages without permission','未经许可查看私人信息侵犯隐私。'),Q('intrusion',3,1,'The noun intrusion is related to?','intrude','introspective','inure','intrude','intrusion 由 intrude 派生。','word-formation'),Q('intrusion',4,1,'The hikers’ intrusion into the nesting area means they?','entered a protected area without welcome','helped birds build nests','watched from the public trail','entered a protected area without welcome','进入不欢迎访客的保护区属于侵扰。')]});
D('intrusive',{etymology:E('Intrusive is formed from intrude with the adjective suffix -ive; it describes unwelcome interference or, in geology, rock forced into older rock.','intrusive'),contexts:[C('intrusive.s1','隐私调查','The survey avoided intrusive questions about patients’ finances unless the information was essential to care.','除非对治疗必不可少，这项调查会避免询问患者财务状况等侵扰性问题。','The survey avoided intrusive questions / about patients’ finances / unless the information was essential / to care.','intrusive.s1 描述干扰隐私或造成不受欢迎打扰的行为。','调查避免在非必要时询问私人财务信息。')],mistakes:[M('The reviewer called the gentle, optional question intrusive even though participants could skip it and no private detail was requested.','The reviewer called the demand for detailed medical records intrusive because it invaded privacy.','可跳过且不涉及私人信息的问题不构成明显侵扰。')],quiz:[Q('intrusive',1,1,'An intrusive question is likely to?','interfere with privacy','request only a public address','be unrelated to anyone’s personal life','interfere with privacy','intrusive 可指侵犯隐私或过度打扰的。'),Q('intrusive',2,2,'In geology, intrusive rock has?','entered older rock as magma and solidified','formed only from loose beach sand','remained a liquid in the air','entered older rock as magma and solidified','地质义指岩浆侵入较老岩层后凝固。'),Q('intrusive',3,1,'Which request is most intrusive?','insisting on a patient’s private records without need','asking a volunteer’s preferred meeting time','offering an optional public-information form','insisting on a patient’s private records without need','无必要索取私人病历会侵犯隐私。'),Q('intrusive',4,1,'Intrusive is the adjective related to?','intrude','introvert','invariable','intrude','intrusive 由 intrude 派生。','word-formation')]});
D('intuitive',{etymology:E('Intuitive comes through intuition from Latin intueri “to look at, consider”; it describes knowledge by immediate insight or something easy to grasp.','intuitive'),contexts:[C('intuitive.s2','产品设计','The redesigned ticket machine has an intuitive layout, so first-time visitors can choose a route without reading a manual.','重新设计的售票机布局直观易懂，初次使用的乘客无需阅读说明书就能选择路线。','The redesigned ticket machine has an intuitive layout / so first-time visitors can choose a route / without reading a manual.','intuitive.s2 指无需专门说明就容易理解或使用的。','新用户能直接选路线，说明界面易懂。')],mistakes:[M('The interface was intuitive because every first-time user needed a lengthy lesson to locate the purchase button.','The interface was intuitive because first-time users could locate the purchase button without instruction.','用户需要长时间教学，说明界面并不直观。')],quiz:[Q('intuitive',1,1,'An intuitive judgment comes from?','immediate insight rather than step-by-step proof','a detailed laboratory calculation only','a printed list of instructions','immediate insight rather than step-by-step proof','intuitive.s1 指来自直觉或直接领会的。'),Q('intuitive',2,2,'An intuitive control panel is?','easy to understand without special instruction','usable only after a long course','designed to hide every control','easy to understand without special instruction','intuitive.s2 表示容易理解或使用的。'),Q('intuitive',3,1,'Which design is intuitive?','a clear map whose symbols need no explanation','a control board with unlabeled switches','a form that users cannot complete unaided','a clear map whose symbols need no explanation','无需解释即可使用的地图布局较直观。'),Q('intuitive',4,1,'The opposite of intuitive in this design context is?','confusing to a first-time user','clear at a glance','easy to navigate','confusing to a first-time user','难以理解的设计与 intuitive 相反。','confusable')]});
D('intuitively',{etymology:E('Intuitively is the adverb formed from intuitive plus -ly; it describes acting by immediate insight rather than a step-by-step argument.','intuitively'),contexts:[C('intuitively.s1','数学学习','Although she could not yet prove the pattern, Lina intuitively sensed that each new term doubled the previous one.','虽然还不能证明这个规律，莉娜凭直觉感到每一项都是前一项的两倍。','Although she could not yet prove the pattern / Lina intuitively sensed / that each new term doubled / the previous one.','intuitively 表示凭直接感觉或领会，而非先完成逐步证明。','她先凭直觉发现规律，证明尚未完成。')],mistakes:[M('The student intuitively solved the problem by following a written proof line by line and making no immediate judgment.','The student intuitively guessed the likely pattern before working through a formal proof.','逐行依据书面证明属于系统推演，不是凭直觉判断。')],quiz:[Q('intuitively',1,1,'To understand something intuitively is to understand it?','through immediate insight','only after memorizing a long manual','by refusing to form any view','through immediate insight','intuitively 指凭直觉地理解。'),Q('intuitively',2,1,'Which decision was made intuitively?','she sensed the safer route before calculating distances','he compared every route using a spreadsheet','they followed the posted instruction exactly','she sensed the safer route before calculating distances','她先凭感觉判断路线，属于 intuitively。'),Q('intuitively',3,1,'Intuitively is the adverb from?','intuitive','intuitionless','intuit','intuitive','intuitively 由形容词 intuitive 加 -ly 构成。','word-formation'),Q('intuitively',4,1,'An intuitively appealing explanation may feel convincing?','without a full step-by-step proof','only after it has been translated','because it contains no idea','without a full step-by-step proof','直觉上有吸引力不代表已有完整证明。')]});
D('inurbane',{etymology:E('Inurbane combines in- “not” with urbane, from Latin urbanus “of the city”; it describes a lack of polished courtesy or refinement.','inurbane'),contexts:[C('inurbane.s1','社交礼仪','The host’s inurbane reply—“Go find your own chair”—made the visiting speaker feel unwelcome.','主人粗鲁地回道“自己找椅子去”，让来访演讲者感到不受欢迎。','The host’s inurbane reply / “Go find your own chair” / made the visiting speaker / feel unwelcome.','inurbane 表示缺乏礼貌和文雅，语气较正式。','主人用生硬无礼的话回应客人。')],mistakes:[M('The reviewer called the host inurbane because she warmly welcomed every guest and politely offered a seat.','The reviewer called the host inurbane because she dismissed guests with curt, discourteous remarks.','热情礼貌地接待客人不能作为 inurbane 的例证。')],quiz:[Q('inurbane',1,1,'An inurbane remark is?','rude and lacking polished courtesy','warmly polite','a mathematical constant','rude and lacking polished courtesy','inurbane 指不礼貌、不文雅的。'),Q('inurbane',2,1,'Which response sounds inurbane?','“Stop bothering me; find your own way out.”','“Welcome; may I show you to a seat?”','“Thank you for letting me know.”','“Stop bothering me; find your own way out.”','粗暴赶人缺乏礼貌。'),Q('inurbane',3,1,'The prefix in- in inurbane means?','not','again','between','not','此处 in- 表示否定。','word-formation'),Q('inurbane',4,1,'Inurbane is closest to?','discourteous','gracious','intuitive','discourteous','discourteous 同样表示无礼的。','confusable')]});
D('inurbanity',{etymology:E('Inurbanity is formed from inurbane with the noun suffix -ity and means uncultivated or discourteous behavior.','inurbanity'),contexts:[C('inurbanity.s1','会议礼仪','The chair apologized for the inurbanity of interrupting the guest repeatedly before she could finish her answer.','主席为自己在客人尚未回答完时屡次打断的粗鲁行为道了歉。','The chair apologized / for the inurbanity of interrupting the guest repeatedly / before she could finish her answer.','inurbanity 指粗鲁或缺少礼貌的行为，属于正式用词。','反复打断发言者被承认为失礼行为。')],mistakes:[M('The report cited the moderator’s inurbanity because she listened patiently, thanked each speaker, and never interrupted.','The report cited the moderator’s inurbanity when she mocked a speaker and cut off every reply.','耐心倾听并致谢不是粗鲁失礼。')],quiz:[Q('inurbanity',1,1,'Inurbanity refers to?','rude or uncultivated behavior','a person’s inner reflection','the quality of staying unchanged','rude or uncultivated behavior','inurbanity 指粗鲁无礼的行为。'),Q('inurbanity',2,1,'Which action displays inurbanity?','mocking a guest while cutting off her answer','offering a guest time to speak','thanking a visitor for a question','mocking a guest while cutting off her answer','嘲笑并打断客人体现失礼。'),Q('inurbanity',3,1,'Inurbanity is the noun related to?','inurbane','inure','inversion','inurbane','inurbanity 是形容词 inurbane 的名词形式。','word-formation'),Q('inurbanity',4,1,'A formal complaint about inurbanity would concern?','discourteous conduct','a lack of mathematical proof','a medical procedure','discourteous conduct','该词讨论的是无礼行为。')]});
D('inure',{etymology:E('Inure developed from an older phrase meaning to bring into use or practice; it now commonly means accustom to hardship, and in formal use may mean take effect for someone’s benefit.','inure'),contexts:[C('inure.s1','艰苦训练','Years of winter fieldwork had inured the rescue team to freezing rain and long nights outdoors.','多年的冬季野外工作使救援队习惯了冻雨和漫长的户外夜晚。','Years of winter fieldwork / had inured the rescue team / to freezing rain / and long nights outdoors.','inure.s1 常用于 inure someone to something，指使其逐渐习惯不快或困难。','多年经历让队员对恶劣天气不再陌生。')],mistakes:[M('The first night in the storm inured the new volunteer to the cold instantly, although she remained shivering and unable to work.','Repeated winter shifts gradually inured the volunteer to working in the cold.','一次经历且仍无法适应，不支持“逐渐习惯”的意思。')],quiz:[Q('inure',1,1,'To inure someone to hardship is to?','make them accustomed to it over time','make the hardship disappear at once','issue them an invoice','make them accustomed to it over time','inure.s1 指使人逐渐适应困难。'),Q('inure',2,2,'In formal legal wording, “the benefit shall inure to her” means it will?','take effect for her benefit','make her accustomed to rain','be canceled as invalid','take effect for her benefit','inure.s2 可指利益归于某人或对其生效。'),Q('inure',3,1,'Which sentence uses inure correctly?','Daily practice inured him to performing under pressure.','The coach inured the score by writing it down.','The storm inured the door open with a key.','Daily practice inured him to performing under pressure.','inure 常与 to 连用，表示使逐渐习惯。','collocation'),Q('inure',4,1,'Inure is closest in sense to “accustom” when it takes?','a person and to + a difficult condition','a price and from + a receipt','a place and under + a color','a person and to + a difficult condition','该结构常为 inure someone to something。','grammar')]});
D('invader',{etymology:E('Invader is formed from invade, from Latin invadere “to enter or attack,” with the agent suffix -er.','invader'),contexts:[C('invader.s1','生态保护','The survey team removed each invasive beetle before it could establish a breeding colony as an invader in the orchard.','调查队在每只入侵性甲虫于果园建立繁殖群前将其清除。','The survey team removed each invasive beetle / before it could establish / a breeding colony / as an invader in the orchard.','invader 指以敌对或有害方式进入某地的人或生物。','甲虫进入果园并扩散繁殖，会成为生态入侵者。')],mistakes:[M('The border guards called the invited aid workers invaders even though they entered through the authorized checkpoint with permits.','The border guards called the armed group that crossed without permission invaders.','经许可入境的援助人员不属于入侵者。')],quiz:[Q('invader',1,1,'An invader enters a place as?','an enemy or harmful presence','an invited guest','a neutral measurement','an enemy or harmful presence','invader 指以敌对或有害方式进入者。'),Q('invader',2,1,'Which might be an ecological invader?','a nonnative insect spreading through a crop','a native plant confined to its usual habitat','a labeled seed packet in storage','a nonnative insect spreading through a crop','扩散并危害作物的外来昆虫可称生态入侵者。'),Q('invader',3,1,'Invader is formed from which verb?','invade','invalidate','invite','invade','invader 源于 invade。','word-formation'),Q('invader',4,1,'A force that crosses a border to seize territory is an?','invader','introvert','inventor','invader','夺取领土的武装力量是侵略者。')]});
D('invalidate',{etymology:E('Invalidate combines in- “not” with valid, from Latin validus “strong”; it means make something legally ineffective or show that an argument does not hold.','invalidate'),contexts:[C('invalidate.s1','合同审查','The court invalidated the clause because it conflicted with the consumer-protection statute.','法院认定该条款与消费者保护法相冲突，因此使其失效。','The court invalidated the clause / because it conflicted / with the consumer-protection statute.','invalidate 指使法律文件或论证失效、站不住脚。','条款与法规冲突，因此不再具有法律效力。')],mistakes:[M('The court invalidated the contract by confirming that every clause was lawful and fully enforceable.','The court invalidated the contract after finding that a required signature was missing.','确认所有条款有效与使合同失效相矛盾。')],quiz:[Q('invalidate',1,1,'To invalidate a contract is to?','make it legally ineffective','make it easier to read','sign it on behalf of both parties','make it legally ineffective','invalidate 可指使合同在法律上无效。'),Q('invalidate',2,1,'A counterexample can invalidate a claim by?','showing that the claim is false','making the claim more colorful','translating the claim into another language','showing that the claim is false','反例可以证明论断不成立。'),Q('invalidate',3,1,'Which event may invalidate a document?','a legally required signature is missing','the paper is stored in a blue folder','the document has a clear title','a legally required signature is missing','缺少法定签名可能使文件无效。'),Q('invalidate',4,1,'Invalidate is closest to?','nullify','confirm','inure','nullify','nullify 也表示使无效。','confusable')]});
D('invalidity',{etymology:E('Invalidity is formed from invalid plus -ity; it names a state of being legally or logically invalid, and in older or formal use may refer to illness or disability.','invalidity'),contexts:[C('invalidity.s1','法律文件','The review focused on the invalidity of the permit, which had been issued without the required approval.','审查重点是该许可证的无效性，因为它未经必要批准便已签发。','The review focused on the invalidity of the permit / which had been issued / without the required approval.','invalidity.s1 指法律或逻辑上的无效状态。','许可证缺少必要批准，因此有效性受到质疑。')],mistakes:[M('The permit’s invalidity was established even though it had every required signature and remained legally enforceable.','The permit’s invalidity was established because a required approval was absent.','文件既有全部签署又可依法执行，与无效结论冲突。')],quiz:[Q('invalidity',1,1,'The invalidity of a permit means its?','lack of legal validity','official approval','physical size','lack of legal validity','invalidity.s1 指法律无效。'),Q('invalidity',2,2,'In older formal usage, invalidity may refer to?','a state of illness or disability','a mathematical constant','a court’s approval of a contract','a state of illness or disability','invalidity.s2 可指病弱或伤残状态，属于较旧或正式用法。'),Q('invalidity',3,1,'Which fact supports a finding of legal invalidity?','the required approval was never obtained','the permit is printed in large type','the holder renewed it on time','the required approval was never obtained','缺少必要批准可导致法律无效。'),Q('invalidity',4,1,'Invalidity is the noun form related to?','invalid','intuitive','invariable','invalid','invalidity 由 invalid 加 -ity 构成。','word-formation')]});
D('invariable',{etymology:E('Invariable combines in- “not” and variable, ultimately from Latin variabilis; it describes something that does not change and can also be a constant quantity.','invariable'),contexts:[C('invariable.s1','实验流程','The laboratory used an invariable calibration interval of exactly six months for every instrument in the program.','该实验室对项目中的每台仪器都采用固定不变的六个月校准间隔。','The laboratory used an invariable calibration interval / of exactly six months / for every instrument / in the program.','invariable.s1 作形容词，表示在各种情况下都不改变的。','所有仪器都使用同一固定间隔。')],mistakes:[M('The schedule was called invariable even though its interval changed from six months to two weeks every time.','The schedule was called invariable because the interval remained six months throughout.','间隔反复变化不能称为不变。')],quiz:[Q('invariable',1,1,'An invariable rule?','stays the same in each case','changes whenever someone asks','has no stated application','stays the same in each case','invariable 表示始终不变的。'),Q('invariable',2,2,'In mathematics, an invariable may be?','a quantity that remains constant','a value that changes at every step','a paragraph’s opening space','a quantity that remains constant','invariable.s2 可指不变量或常数。'),Q('invariable',3,1,'Which is an invariable condition?','the fee is fixed at $10 for every applicant','the fee rises for each new applicant','the fee is chosen by a daily lottery','the fee is fixed at $10 for every applicant','每位申请者费用相同，说明条件不变。'),Q('invariable',4,1,'The prefix in- in invariable signals?','not','again','under','not','in- 在此表示否定。','word-formation')]});
D('invariance',{etymology:E('Invariance is formed from invariant with -ance; it names the property of remaining unchanged under a specified transformation or condition.','invariance'),contexts:[C('invariance.s1','数学建模','The team checked the invariance of the equation under rotation by substituting rotated coordinates into both sides.','团队通过把旋转后的坐标代入等式两边，检验该方程在旋转下的不变性。','The team checked the invariance of the equation under rotation / by substituting rotated coordinates / into both sides.','invariance 指在特定变换或条件下保持不变的性质。','旋转坐标后等式仍成立，体现旋转不变性。')],mistakes:[M('The equation had rotational invariance even though rotating the coordinates changed its predicted result each time.','The equation had rotational invariance because its result stayed the same after coordinates were rotated.','旋转后结果改变，便不具备旋转不变性。')],quiz:[Q('invariance',1,1,'In mathematics, invariance is the property of?','remaining unchanged under a specified transformation','changing unpredictably under every operation','being printed in a fixed font','remaining unchanged under a specified transformation','invariance 指在特定变换下保持不变的性质。'),Q('invariance',2,1,'A test for rotational invariance asks whether a result changes when?','the coordinates are rotated','the page color is changed','the equation is read aloud','the coordinates are rotated','旋转坐标后结果是否改变可检验旋转不变性。'),Q('invariance',3,1,'Invariance is the noun related to?','invariant','invader','iridescent','invariant','invariance 由 invariant 加 -ance 构成。','word-formation'),Q('invariance',4,1,'If a model’s output is invariant to a harmless rescaling, it?','stays the same after that rescaling','becomes a different model every time','cannot accept an input','stays the same after that rescaling','输出不因该缩放改变，说明具有相应不变性。')]});
D('invasive',{etymology:E('Invasive is formed from invade with -ive; it describes harmful spreading or a medical procedure that enters the body.','invasive'),contexts:[C('invasive.s2','医疗知情同意','The doctor explained that the biopsy was invasive because it required inserting a needle through the skin to collect tissue.','医生解释说，这项活检属于有创操作，因为需要将针穿过皮肤采集组织。','The doctor explained / that the biopsy was invasive / because it required inserting a needle / through the skin to collect tissue.','invasive.s2 在医疗语境中表示需要进入身体的有创操作。','针穿过皮肤取样，符合医疗有创操作的特点。')],mistakes:[M('The clinic described a simple external photograph as invasive even though no instrument entered the body and no tissue was touched.','The clinic described the needle biopsy as invasive because it entered the body to collect tissue.','仅在体外拍照没有进入身体，不属于有创操作。')],quiz:[Q('invasive',1,2,'A medical procedure is invasive when it?','enters the body, often by incision or instrument','uses only an external conversation','takes place in a large hospital','enters the body, often by incision or instrument','invasive.s2 指进入身体的有创医疗操作。'),Q('invasive',2,1,'An invasive plant is one that?','spreads into an area and can cause harm','grows only in a greenhouse pot','never reproduces','spreads into an area and can cause harm','invasive.s1 可描述扩散并造成危害的生物。'),Q('invasive',3,2,'Which is most clearly an invasive medical test?','a tissue sample taken through a needle','a blood-pressure reading with a cuff','a doctor asking about symptoms','a tissue sample taken through a needle','针穿刺取组织会进入身体。'),Q('invasive',4,1,'An invasive species may threaten?','native plants and animals','only the spelling of a word','a patient’s appointment time','native plants and animals','入侵物种可能危害本地生态。')]});
D('inventiveness',{etymology:E('Inventiveness is formed from inventive with -ness and describes the ability to devise original ideas, devices, or solutions.','inventiveness'),contexts:[C('inventiveness.s1','工程竞赛','The judges praised the students’ inventiveness when they built a water filter from safe, inexpensive materials.','评委称赞学生们的创造力，因为他们用安全、便宜的材料做出了一个水过滤器。','The judges praised the students’ inventiveness / when they built a water filter / from safe, inexpensive materials.','inventiveness 指提出新颖想法或解决方案的能力。','学生用简单材料设计了有效装置，体现创造力。')],mistakes:[M('The judges called the project inventive even though the team copied an existing design exactly and offered no new idea.','The judges praised the project’s inventiveness because the team devised a new filter design.','完全照搬而没有新想法，不能体现创造力。')],quiz:[Q('inventiveness',1,1,'Inventiveness is the ability to?','create original ideas or solutions','repeat a fixed instruction without change','record a measurement accurately','create original ideas or solutions','inventiveness 指创造新想法或方案的能力。'),Q('inventiveness',2,1,'Which project shows inventiveness?','a new low-cost filter made from available materials','a verbatim copy of a standard kit','a list copied from a manual','a new low-cost filter made from available materials','利用现有材料设计新方案体现创造力。'),Q('inventiveness',3,1,'Inventiveness is related to which adjective?','inventive','invariable','invisible','inventive','inventiveness 由 inventive 加 -ness 构成。','word-formation'),Q('inventiveness',4,1,'A lack of inventiveness would most likely mean?','few original approaches','many novel solutions','an unusually clear explanation','few original approaches','缺少创造力意味着新颖方案较少。')]});
D('inventor',{etymology:E('Inventor is formed from invent, from Latin invenire “to find,” with the agent suffix -or; it names someone who creates something new.','inventor'),contexts:[C('inventor.s1','专利档案','The inventor submitted detailed drawings showing how the folding hinge could be manufactured and repaired.','发明者提交了详细图纸，说明这种折叠铰链如何制造和维修。','The inventor submitted detailed drawings / showing how the folding hinge / could be manufactured and repaired.','inventor 指创造新装置、方法或其他事物的人。','图纸解释了新铰链的设计与生产方式。')],mistakes:[M('The article called the person who merely purchased the patented hinge its inventor, although another engineer designed it.','The article called the engineer who designed the new hinge its inventor.','购买发明产品的人不因此成为该发明的创造者。')],quiz:[Q('inventor',1,1,'An inventor is someone who?','creates something new','only buys finished products','repairs every object they see','creates something new','inventor 指发明或创造新事物的人。'),Q('inventor',2,1,'Which person is the inventor of a device?','the engineer who devised its original mechanism','the first customer to buy it','the clerk who filed a copy of its manual','the engineer who devised its original mechanism','设计出装置原理的人是发明者。'),Q('inventor',3,1,'Inventor is related to which verb?','invent','invert','inure','invent','inventor 由 invent 加表示人的 -or 构成。','word-formation'),Q('inventor',4,1,'A patent document may identify the?','inventor who created the claimed device','visitor who saw the device once','invariable price of the device','inventor who created the claimed device','专利资料会记载该装置的发明者。')]});
D('inversion',{etymology:E('Inversion comes through Latin inversio from invertere “to turn upside down”; it can name reversed order, including grammar, or a weather layer with warmer air above cooler air.','inversion'),contexts:[C('inversion.s2','天气预报','A temperature inversion trapped cool air near the ground beneath a warmer layer, allowing pollution to accumulate in the valley.','逆温使冷空气滞留在近地面，并被上方暖空气覆盖，污染物因此积聚在山谷中。','A temperature inversion trapped cool air near the ground / beneath a warmer layer / allowing pollution to accumulate / in the valley.','inversion.s2 指大气中暖空气位于较冷近地层上方的逆温现象。','暖空气覆盖冷空气，抑制垂直混合并使污染积聚。')],mistakes:[M('The forecast called the normal pattern an inversion because cold air lay above a warm surface layer.','The forecast called the pattern an inversion because a warmer layer lay above cooler air near the ground.','暖冷空气的层次与逆温定义相反。')],quiz:[Q('inversion',1,2,'A temperature inversion occurs when?','warmer air lies above cooler air near the ground','the ground becomes warmer than every layer above','wind changes direction at the coast','warmer air lies above cooler air near the ground','inversion.s2 指近地冷空气上方出现暖空气层。'),Q('inversion',2,1,'In grammar, inversion may mean?','reversing the usual word order','adding a plural ending','removing every verb','reversing the usual word order','inversion.s1 可指语序颠倒。'),Q('inversion',3,2,'Why can a temperature inversion worsen valley pollution?','it limits vertical mixing that would disperse pollutants','it turns all pollutants into water','it removes the valley walls','it limits vertical mixing that would disperse pollutants','逆温抑制空气混合，污染不易扩散。'),Q('inversion',4,1,'Which phrase uses inversion in the grammatical sense?','“Rarely have we seen such fog” reverses normal order','the forecast predicts warmer air above cool ground','a ladder is placed beside the wall','“Rarely have we seen such fog” reverses normal order','助动词前置体现语序倒装。')]});
D('invertebrate',{etymology:E('Invertebrate combines the negative prefix in- with vertebrate, whose root refers to the backbone; it can describe an animal lacking a backbone or be the noun for such an animal.','invertebrate'),contexts:[C('invertebrate.s2','潮间带调查','The students recorded each invertebrate they found under the rocks, including crabs, snails, and sea anemones.','学生们记录了在岩石下发现的每种无脊椎动物，包括螃蟹、蜗牛和海葵。','The students recorded each invertebrate / they found under the rocks / including crabs, snails, and sea anemones.','invertebrate.s2 作名词，指没有脊柱的动物。','列举的螃蟹、蜗牛和海葵都没有脊柱。')],mistakes:[M('The field guide classified a dog as an invertebrate because it has a skull and a backbone.','The field guide classified a snail as an invertebrate because it has no backbone.','狗有脊柱，不能归为无脊椎动物。')],quiz:[Q('invertebrate',1,2,'An invertebrate is an animal without a?','backbone','shell of any kind','nervous system','backbone','invertebrate.s2 指没有脊柱的动物。'),Q('invertebrate',2,1,'An invertebrate animal is one that?','lacks a backbone','has a vertebral column','must live in the ocean','lacks a backbone','invertebrate.s1 作形容词，表示无脊椎的。'),Q('invertebrate',3,2,'Which animal is an invertebrate?','a sea anemone','a lizard','a sparrow','a sea anemone','海葵没有脊柱。'),Q('invertebrate',4,1,'The prefix in- in invertebrate means?','without or not','before','together','without or not','此处 in- 表否定。','word-formation')]});
D('investigative',{etymology:E('Investigative is formed from investigate with -ive; investigate ultimately comes from Latin vestigium “track or footprint,” suggesting the search for evidence.','investigative'),contexts:[C('investigative.s1','新闻报道','The investigative series compared public contracts with company records and interviewed residents who had raised concerns.','这组调查报道将公共合同与公司记录进行比较，并采访了提出疑虑的居民。','The investigative series compared public contracts / with company records / and interviewed residents / who had raised concerns.','investigative 描述以查明事实、搜集证据为目的的工作。','报道比对文件并采访知情者，体现调查性。')],mistakes:[M('The editor called the article investigative even though it repeated a press release and checked no records or witnesses.','The editor called the article investigative because it checked records and interviewed witnesses.','仅重复新闻稿而未查证，不符合调查报道的特点。')],quiz:[Q('investigative',1,1,'Investigative reporting is chiefly concerned with?','finding facts through research and evidence','repeating an announcement without checking it','writing a fictional ending','finding facts through research and evidence','investigative 指以查明事实为目的的调查性工作。'),Q('investigative',2,1,'Which project is investigative?','checking expense records to uncover how funds were used','summarizing a brochure without verifying claims','designing a decorative poster','checking expense records to uncover how funds were used','核查记录以查清资金去向，属于调查。'),Q('investigative',3,1,'Investigative is the adjective formed from?','investigate','investor','inviting','investigate','investigative 由 investigate 派生。','word-formation'),Q('investigative',4,1,'An investigative committee would likely?','gather evidence about what happened','approve every claim without review','sell shares on the market','gather evidence about what happened','调查委员会会搜集证据查明事件。')]});
D('investigator',{etymology:E('Investigator is formed from investigate with the agent suffix -or and names a person who examines a case, event, or research question.','investigator'),contexts:[C('investigator.s1','事故调查','The investigator photographed the damaged railing, interviewed passengers, and preserved the train’s maintenance log.','调查人员拍下受损栏杆，采访乘客，并保存了列车维修日志。','The investigator photographed the damaged railing / interviewed passengers / and preserved / the train’s maintenance log.','investigator 指负责调查案件、事故或研究问题的人。','其工作包括记录现场、访谈和保存证据。')],mistakes:[M('The report called a witness the investigator even though she only described what she had seen and did not examine the case.','The report called the official who collected evidence and interviewed witnesses the investigator.','提供证词的目击者不一定是负责调查的人。')],quiz:[Q('investigator',1,1,'An investigator is someone who?','examines a case or question to find facts','invests money in a company','supervises an exam hall','examines a case or question to find facts','investigator 指调查人员。'),Q('investigator',2,1,'Which task belongs to an accident investigator?','preserving evidence from the scene','issuing a dividend to shareholders','choosing an exam seat','preserving evidence from the scene','保存现场证据是事故调查工作。'),Q('investigator',3,1,'Investigator is formed from which verb?','investigate','invade','inure','investigate','investigator 由 investigate 加 -or 构成。','word-formation'),Q('investigator',4,1,'The investigator interviewed witnesses in order to?','establish what had happened','sell them insurance','ask them to supervise a test','establish what had happened','调查人员通过采访了解事件经过。')]});
D('investor',{etymology:E('Investor is formed from invest, from Latin investire “to clothe or surround,” with the agent suffix -or; in finance it names someone who commits money to an asset or enterprise.','investor'),contexts:[C('investor.s1','创业融资','Each investor reviewed the start-up’s accounts and risks before deciding whether to provide capital.','每位投资者在决定是否提供资金前，都审阅了这家初创企业的账目和风险。','Each investor reviewed the start-up’s accounts and risks / before deciding / whether to provide capital.','investor 指投入资金以期获得回报的人或机构。','投资者先评估企业账目与风险，再决定是否出资。')],mistakes:[M('The article called a customer an investor merely because she bought one product and acquired no financial stake in the company.','The article called the person who supplied capital in exchange for a stake an investor.','购买商品本身不等于向企业投入资本。')],quiz:[Q('investor',1,1,'An investor typically?','commits money to an asset or business','investigates an accident','supervises an examination','commits money to an asset or business','investor 指投入资金的人。'),Q('investor',2,1,'Before investing, a careful investor may review?','the company’s accounts and risks','the weather in another country only','a dictionary’s alphabetical index','the company’s accounts and risks','审阅账目和风险是投资决策的一部分。'),Q('investor',3,1,'Which person is an investor?','someone who provides capital for a business','someone who interviews witnesses','someone who grades an exam','someone who provides capital for a business','提供企业资本的人是投资者。'),Q('investor',4,1,'Investor is related to which verb?','invest','invite','invert','invest','investor 源自 invest。','word-formation')]});
D('invigilate',{etymology:E('Invigilate comes from Latin invigilare “to watch over”; in British English it means supervise candidates during an examination.','invigilate'),contexts:[C('invigilate.s1','考试管理','Two staff members will invigilate the language exam and report any breach of the testing rules.','两名工作人员将监考这场语言考试，并报告任何违反考试规定的行为。','Two staff members will invigilate the language exam / and report / any breach of the testing rules.','invigilate 指在考试期间监考，确保考生遵守规则；该动词常用于英式英语。','工作人员监督考场并处理违规情况。')],mistakes:[M('The lecturer invigilated the exam by leaving candidates alone in the room and never checking whether rules were followed.','The lecturer invigilated the exam by remaining in the room and supervising candidates.','离开考场且不监督考生，不算监考。')],quiz:[Q('invigilate',1,1,'To invigilate an exam is to?','supervise candidates while they take it','write every candidate’s answers','invest money in the exam board','supervise candidates while they take it','invigilate 指监考。'),Q('invigilate',2,1,'Who is most likely to invigilate?','a staff member supervising a test room','a student taking the test','an investor reviewing company accounts','a staff member supervising a test room','监考员负责监督考试过程。'),Q('invigilate',3,1,'Which sentence uses invigilate correctly?','Ms Lee will invigilate the mathematics paper.','Ms Lee invigilated her savings into a fund.','Ms Lee invigilates the question by answering it.','Ms Lee will invigilate the mathematics paper.','invigilate 的宾语常是考试。','collocation'),Q('invigilate',4,1,'Invigilate is closest in meaning to?','proctor','invest','invalidate','proctor','proctor 作动词也可表示监考。','confusable')]});
D('invincible',{etymology:E('Invincible comes from Latin invincibilis, formed with in- “not” and vincere “to conquer”; it means impossible to defeat or overcome.','invincible'),contexts:[C('invincible.s1','体育评论','The team looked invincible through the first half of the season, but two late losses showed that it could be beaten.','赛季上半程这支队伍看似不可战胜，但后来两场失利表明它也会被击败。','The team looked invincible / through the first half of the season / but two late losses showed / that it could be beaten.','invincible 形容似乎无法被击败或克服的对象。','前期连胜让队伍显得强大，后来失利说明这只是当时的判断。')],mistakes:[M('The coach called the champion invincible after she had been defeated in every round of the tournament.','The coach called the unbeaten champion nearly invincible after a long winning streak.','每轮都落败不能支持“不可战胜”的描述。')],quiz:[Q('invincible',1,1,'Something invincible is?','impossible or extremely difficult to defeat','already defeated','easy to overlook','impossible or extremely difficult to defeat','invincible 指不可战胜或难以克服的。'),Q('invincible',2,1,'Which team seemed invincible?','one that won every match for several seasons','one that lost every match','one that never entered a competition','one that won every match for several seasons','长期连胜的队伍看起来难以击败。'),Q('invincible',3,1,'The prefix in- in invincible means?','not','within','again','not','invincible 中 in- 表示否定。','word-formation'),Q('invincible',4,1,'An invincible obstacle would be one that?','cannot be overcome','has already been moved','is easy to avoid','cannot be overcome','invincible 也可形容无法克服的困难。')]});
D('invisibly',{etymology:E('Invisibly is formed from invisible, ultimately from Latin invisibilis “not able to be seen,” with the adverb suffix -ly.','invisibly'),contexts:[C('invisibly.s1','动物观察','The moth rested invisibly against the bark, its mottled wings blending into the tree’s rough surface.','飞蛾停在树皮上几乎看不见，斑驳的翅膀与粗糙树面融为一体。','The moth rested invisibly against the bark / its mottled wings blending / into the tree’s rough surface.','invisibly 表示以肉眼不易看见的方式。','翅膀颜色与树皮相近，使飞蛾难以察觉。')],mistakes:[M('The bright red marker stood invisibly against a white wall and was immediately obvious from across the room.','The pale marker blended invisibly into the wall and was difficult to notice.','鲜红标记清晰可见，与 invisibly 矛盾。')],quiz:[Q('invisibly',1,1,'To move invisibly is to move?','so that one cannot be seen','in a very loud manner','without changing direction','so that one cannot be seen','invisibly 表示看不见地。'),Q('invisibly',2,1,'Which object is positioned invisibly?','a moth that blends into the bark','a flashing lamp in a dark room','a bright flag on an open hill','a moth that blends into the bark','与背景融为一体的飞蛾难以被看到。'),Q('invisibly',3,1,'Invisibly is the adverb from?','invisible','invariable','invasive','invisible','invisibly 由 invisible 加 -ly 构成。','word-formation'),Q('invisibly',4,1,'If a stain is invisibly small, it is?','too small to be seen','brightly colored','easy to measure by eye','too small to be seen','该词指无法看见地。')]});
D('inviting',{etymology:E('Inviting is the present participle of invite and also an adjective meaning pleasant in a way that encourages approach or participation.','inviting'),contexts:[C('inviting.s1','餐厅介绍','The café’s inviting courtyard, shaded tables, and fresh bread made the travelers want to stop for lunch.','这家咖啡馆宜人的庭院、遮阴桌位和新鲜面包让旅客想停下来吃午饭。','The café’s inviting courtyard / shaded tables / and fresh bread / made the travelers want to stop for lunch.','inviting 作形容词，指令人愉快并想靠近、加入或接受的。','舒适环境和香味让人愿意停留。')],mistakes:[M('The hotel described its inviting lobby as dark, cold, and closed to visitors, with no place to sit.','The hotel described its warm, comfortable lobby as inviting to arriving guests.','令人不想接近的环境与 inviting 的吸引力相反。')],quiz:[Q('inviting',1,1,'An inviting room makes people want to?','enter or stay there','leave immediately','avoid looking at it','enter or stay there','inviting 描述令人想靠近或停留的环境。'),Q('inviting',2,1,'Which offer sounds inviting?','a relaxed picnic with shade and fresh food','a locked room with no seating','a warning that all visitors must leave','a relaxed picnic with shade and fresh food','舒适且有食物的野餐容易吸引人参加。'),Q('inviting',3,1,'Choose the adjective: “The warm lights created an ___ atmosphere.”','inviting','invite','invitation','inviting','空格修饰 atmosphere，需要形容词 inviting。','word-formation'),Q('inviting',4,1,'Inviting is closest in this context to?','appealing','forbidding','invisible','appealing','appealing 同样可表示吸引人的。','confusable')]});
D('invocation',{etymology:E('Invocation comes from Latin invocatio, from invocare “to call upon”; it can name a prayer or an appeal to an authority, rule, or principle.','invocation'),contexts:[C('invocation.s2','法律辩论','The lawyer’s invocation of the equal-protection clause framed the challenge to the city’s policy.','律师援引平等保护条款，对该市政策提出质疑。','The lawyer’s invocation of the equal-protection clause / framed the challenge / to the city’s policy.','invocation.s2 指在论证中援引法律、原则或权威作为依据。','律师把宪法条款作为质疑政策的依据。')],mistakes:[M('The brief contained an invocation of the statute but cited no provision and did not rely on the law in its argument.','The brief contained an invocation of the statute and explained how its provisions supported the argument.','提到法律却不引用或依赖它，不能算有效援引。')],quiz:[Q('invocation',1,2,'An invocation of a law in an argument is?','citing it as support','ignoring it completely','turning it into a prayer','citing it as support','invocation.s2 指援引法律作为论据。'),Q('invocation',2,1,'At a ceremony, an invocation may be?','a prayer asking for divine help','a financial invoice','a list of exam candidates','a prayer asking for divine help','invocation.s1 可指祷词或祈求。'),Q('invocation',3,2,'Which sentence uses invocation in the legal sense?','Her invocation of the rule supported the appeal.','The choir sang an invocation before the ceremony.','The cashier prepared an invoice for the order.','Her invocation of the rule supported the appeal.','援引规则支持上诉，属于法律论证用法。'),Q('invocation',4,1,'Invocation is related to which verb?','invoke','invest','invert','invoke','invocation 源自 invoke。','word-formation')]});
D('invoice',{etymology:E('Invoice is an established English term for a document listing supplied goods or services and the amount due; its older history is associated with a written list sent to a customer.','invoice'),contexts:[C('invoice.s1','采购付款','The supplier’s invoice listed twelve replacement filters, the delivery charge, and the payment deadline.','供应商的发票列出了十二个替换滤芯、运费和付款期限。','The supplier’s invoice listed / twelve replacement filters / the delivery charge / and the payment deadline.','invoice.s1 作名词，指列明商品或服务及应付金额的单据。','单据列出数量、费用和付款期限。')],mistakes:[M('The buyer approved the invoice even though it listed no goods, services, amount, or payment information.','The buyer approved the invoice after checking its itemized goods and total due.','没有项目和应付款信息，不能满足发票或账单的功能。')],quiz:[Q('invoice',1,1,'An invoice usually states?','what was supplied and how much is due','a person’s private thoughts','the rules for supervising an exam','what was supplied and how much is due','invoice.s1 是列明供货项目和应付款的单据。'),Q('invoice',2,2,'To invoice a client is to?','send the client a bill for services','pay the client’s salary','ask the client to invigilate a test','send the client a bill for services','invoice.s2 作动词表示向客户开账单。'),Q('invoice',3,1,'Which document is an invoice?','an itemized bill for repair work','a thank-you note without charges','a schedule of exam rooms','an itemized bill for repair work','维修项目和费用清单属于发票或账单。'),Q('invoice',4,1,'A customer checks an invoice mainly to verify?','the items charged and the amount due','the writer’s personality','the weather on delivery day','the items charged and the amount due','发票用于核对收费项目与应付金额。')]});
D('invoke',{etymology:E('Invoke comes from Latin invocare, “to call upon,” combining in- and vocare “to call”; it can mean cite an authority, pray for help, or bring a feeling or memory to mind.','invoke'),contexts:[C('invoke.s3','文学评论','The old station’s whistle invoked memories of the narrator’s childhood visits to the coast.','旧车站的汽笛唤起了叙述者童年去海岸的回忆。','The old station’s whistle / invoked memories / of the narrator’s childhood visits / to the coast.','invoke.s3 表示某事物引起或唤起感情、记忆等。','汽笛使叙述者想起童年往事。')],mistakes:[M('The familiar song invoked no memories at all but was described as having vividly brought the singer’s childhood back to mind.','The familiar song invoked memories of the singer’s childhood.','“完全没有唤起回忆”与“生动地使其想起”矛盾。')],quiz:[Q('invoke',1,1,'To invoke a legal rule is to?','cite it in support of an action','ignore it while making a claim','send a bill to a client','cite it in support of an action','invoke.s1 指援引法律或规则。'),Q('invoke',2,2,'To invoke a deity is to?','call on the deity for help','issue an invoice to the deity','record a temperature inversion','call on the deity for help','invoke.s2 可指祈求神灵帮助。'),Q('invoke',3,3,'A smell may invoke a memory by?','bringing it to mind','making it legally invalid','turning it into a constant','bringing it to mind','invoke.s3 指唤起回忆。'),Q('invoke',4,3,'Which sentence uses invoke to mean “evoke”?','The old photograph invoked memories of school.','The lawyer invoked the safety regulation.','The worshipper invoked the deity for help.','The old photograph invoked memories of school.','照片唤起了学校时光的记忆，使用的是 s3。','confusable')]});
D('involuntary',{etymology:E('Involuntary combines in- “not” with voluntary, ultimately from Latin voluntarius; it means not chosen or controlled by conscious will.','involuntary'),contexts:[C('involuntary.s1','医学观察','The patient’s involuntary hand tremor continued even when she was resting and trying to keep still.','患者即使休息并努力保持不动，手部仍会不由自主地颤抖。','The patient’s involuntary hand tremor continued / even when she was resting / and trying to keep still.','involuntary 指非本人有意选择或控制的动作，也可指身体反射。','患者无法凭意志停止手部颤抖。')],mistakes:[M('The movement was involuntary because the dancer planned it, practiced it, and began it on a deliberate cue.','The movement was involuntary because it occurred as an uncontrolled reflex.','经过计划并按提示主动开始的动作是自愿的。')],quiz:[Q('involuntary',1,1,'An involuntary action is?','not consciously chosen or controlled','carefully planned in advance','required by a written contract','not consciously chosen or controlled','involuntary 表示非自愿或不由自主的。'),Q('involuntary',2,1,'Which is an involuntary response?','blinking when dust approaches the eye','raising a hand to vote','choosing a seat near the window','blinking when dust approaches the eye','遇到灰尘时眨眼通常是反射动作。'),Q('involuntary',3,1,'The prefix in- in involuntary means?','not','inside','again','not','此处 in- 是否定前缀。','word-formation'),Q('involuntary',4,1,'An involuntary smile may appear?','without a deliberate decision','only after writing down a plan','because the person signed a form','without a deliberate decision','不由自主的微笑不需要刻意决定。')]});
D('involved',{etymology:E('Involved is the past participle of involve, from Latin involvere “to roll into”; as an adjective it can mean participating in something or complicated and detailed.','involved'),contexts:[C('involved.s2','技术说明','The permit process became so involved that applicants needed a checklist to track each document and approval.','许可证申请流程变得十分复杂，申请人需要用清单追踪每份文件和每项审批。','The permit process became so involved / that applicants needed a checklist / to track each document / and approval.','involved.s2 表示复杂且包含许多细节的。','多个文件和审批步骤令流程繁复。')],mistakes:[M('The application was involved because it required one name and one signature on a single page.','The application was involved because it required several forms, inspections, and approvals.','只有一个姓名和签名的简单申请不算复杂。')],quiz:[Q('involved',1,1,'A person involved in a project is?','taking part in it','unaware that it exists','measuring its temperature','taking part in it','involved.s1 指参与某项活动。'),Q('involved',2,2,'An involved procedure is?','complicated and detailed','short and effortless','unrelated to the task','complicated and detailed','involved.s2 指复杂繁琐的。'),Q('involved',3,2,'Which process sounds involved?','one with many forms and approvals','one requiring a single click','one with no steps or decisions','one with many forms and approvals','许多表格和审批构成复杂流程。'),Q('involved',4,1,'In “the people involved,” involved means?','participating in the matter','being difficult to understand','being invariable','participating in the matter','此处指参与其中的人。')]});
D('involvement',{etymology:E('Involvement is formed from involve with -ment and names participation in an activity, situation, or relationship.','involvement'),contexts:[C('involvement.s1','社区项目','Her involvement in the neighborhood garden began with weekend watering and grew into organizing the seed exchange.','她最初在周末为社区花园浇水，后来参与组织种子交换活动。','Her involvement in the neighborhood garden began / with weekend watering / and grew into organizing / the seed exchange.','involvement 指参与某项活动或事务的状态与程度。','她从简单劳动逐渐承担组织工作，体现持续参与。')],mistakes:[M('The report described the volunteer’s involvement in the project even though she never attended, contributed, or communicated with the team.','The report described the volunteer’s involvement in the project because she organized its weekly sessions.','从未参加或贡献不能称为参与项目。')],quiz:[Q('involvement',1,1,'Involvement in a project means?','participation in it','complete separation from it','a legal invoice for it','participation in it','involvement 指参与。'),Q('involvement',2,1,'Which shows community involvement?','organizing weekly activities for local residents','reading a poster but never joining','avoiding every meeting and contribution','organizing weekly activities for local residents','组织活动属于实际参与社区事务。'),Q('involvement',3,1,'Involvement is the noun related to?','involve','invoke','invariable','involve','involvement 由 involve 加 -ment 构成。','word-formation'),Q('involvement',4,1,'A person’s involvement may be described by?','the activities and responsibilities they take on','the color of their notebook','a measurement of ion charge','the activities and responsibilities they take on','参与情况可由承担的活动和职责来描述。')]});
D('iodine',{etymology:E('Iodine was named from Greek ioeides “violet-colored,” referring to the color of its vapor; it is a nonmetal element used in chemistry and in some antiseptic preparations.','iodine'),contexts:[C('iodine.s1','化学实验室','When the sealed vial warmed, violet iodine vapor became visible above the dark crystals.','密封试管升温时，深色晶体上方出现了紫色碘蒸气。','When the sealed vial warmed / violet iodine vapor became visible / above the dark crystals.','iodine 指化学元素碘；某些制剂也含碘，但不能把元素与所有消毒剂混同。','紫色蒸气是碘的典型实验现象。')],mistakes:[M('The lab identified the violet vapor as iodine even though the sample contained no iodine and produced only colorless water vapor.','The lab identified the violet vapor released from the iodine sample as iodine vapor.','无碘样品产生的无色水蒸气不是碘蒸气。')],quiz:[Q('iodine',1,1,'Iodine is a?','chemical element','type of backbone','financial document','chemical element','iodine 是一种化学元素。'),Q('iodine',2,1,'What color can iodine vapor appear?','violet','bright green','opaque white only','violet','碘蒸气可呈紫色。'),Q('iodine',3,1,'Iodine is important in the body partly because it is used by the?','thyroid gland','kneecap','outer ear only','thyroid gland','人体甲状腺会利用碘。'),Q('iodine',4,1,'Which statement is accurate?','some antiseptic preparations contain iodine','every antiseptic is pure iodine','iodine is a type of invoice','some antiseptic preparations contain iodine','某些消毒制剂含有碘，但不等于所有制剂都是碘。')]});
D('ion',{etymology:E('Ion was coined from Greek ion “going,” the present participle of ienai “to go,” because charged particles move toward electrodes.','ion'),contexts:[C('ion.s1','电化学课堂','During electrolysis, each positive ion moved toward the negative electrode while negative ions traveled toward the positive one.','电解过程中，正离子移向负电极，负离子则移向正电极。','During electrolysis / each positive ion moved toward the negative electrode / while negative ions traveled / toward the positive one.','ion 指带正电或负电的原子或原子团。','正负电荷相反的离子分别朝相反电极移动。')],mistakes:[M('The chemist called a neutral atom with equal numbers of protons and electrons an ion even though it carried no net charge.','The chemist called the atom an ion after it gained an electron and acquired a net negative charge.','没有净电荷的原子不是离子。')],quiz:[Q('ion',1,1,'An ion is an atom or group of atoms with?','a positive or negative electric charge','exactly no possible charge','a permanent magnetic north pole only','a positive or negative electric charge','ion 指带正电或负电的原子或原子团。'),Q('ion',2,1,'An atom becomes a negative ion when it?','gains electrons','loses every proton','turns into a molecule without charge','gains electrons','获得电子后会带负电。'),Q('ion',3,1,'Which particle is an ion?','a charged sodium atom','a neutral atom with balanced charges','a page number in a book','a charged sodium atom','带净电荷的钠原子是离子。'),Q('ion',4,1,'Positive and negative ions differ in their?','electrical charge','number of written syllables','place in an invoice','electrical charge','离子的正负由电荷符号决定。')]});
D('ionic',{etymology:E('Ionic is formed from ion with -ic in chemistry; the same spelling also refers to ancient Ionia, its Greek dialect, or the classical Ionic architectural order.','ionic'),contexts:[C('ionic.s1','化学键','Sodium chloride forms an ionic solid in which oppositely charged ions attract one another.','氯化钠形成离子固体，其中带相反电荷的离子彼此吸引。','Sodium chloride forms an ionic solid / in which oppositely charged ions / attract one another.','ionic.s1 表示与离子有关，尤其指由离子间静电吸引形成的。','钠离子与氯离子带相反电荷并相互吸引。')],mistakes:[M('The chemist described a bond between two neutral atoms with no charged particles as ionic.','The chemist described the attraction between oppositely charged ions as ionic.','离子键依赖离子电荷，不是中性原子之间没有电荷的情形。')],quiz:[Q('ionic',1,1,'An ionic bond involves attraction between?','oppositely charged ions','two uncharged pages','two unrelated temperatures','oppositely charged ions','ionic.s1 指离子之间的相互作用。'),Q('ionic',2,2,'An Ionic column belongs to which tradition?','classical Greek architecture','modern chemistry only','a financial audit','classical Greek architecture','ionic.s2 指古典建筑中的爱奥尼亚式。'),Q('ionic',3,3,'Ionic as a noun can refer to?','an ancient Greek dialect','a charged particle only','a legal clause','an ancient Greek dialect','ionic.s3 可指古希腊爱奥尼亚方言。'),Q('ionic',4,1,'Which material is commonly described as ionic?','a crystal made of positive and negative ions','a gas of only neutral atoms','a sheet of uncharged paper','a crystal made of positive and negative ions','由正负离子构成的晶体可称离子晶体。')]});
D('ionize',{etymology:E('Ionize is formed from ion with the verb suffix -ize; it means cause atoms or molecules to become ions, or undergo that change.','ionize'),contexts:[C('ionize.s1','放射化学','The detector measures radiation energetic enough to ionize gas molecules inside its chamber.','探测器测量足以使腔内气体分子电离的辐射。','The detector measures radiation / energetic enough to ionize gas molecules / inside its chamber.','ionize.s1 作及物动词，表示使原子或分子失去或获得电子而形成离子。','辐射向分子提供能量，使其转变为离子。')],mistakes:[M('The technician said the radiation ionized the gas even though every molecule stayed neutral and no electrons were transferred.','The technician said the radiation ionized the gas after molecules lost electrons and became charged.','分子未带电且没有电子变化，就没有发生电离。')],quiz:[Q('ionize',1,1,'To ionize an atom is to?','cause it to gain or lose electrons and become charged','turn it into a larger planet','make it invisible without changing it','cause it to gain or lose electrons and become charged','ionize.s1 指使原子形成带电离子。'),Q('ionize',2,2,'A gas can ionize when its atoms?','become changed into ions','remain neutral in every respect','are listed on an invoice','become changed into ions','ionize.s2 可作不及物用法，表示气体或原子发生电离。'),Q('ionize',3,1,'Which source may ionize a gas?','sufficiently energetic radiation','a quiet spoken sentence','a printed table of contents','sufficiently energetic radiation','足够强的辐射能使气体电离。'),Q('ionize',4,1,'Ionize is the verb formed from?','ion','ionicity','inversion','ion','ionize 由 ion 加 -ize 构成。','word-formation')]});
D('ionosphere',{etymology:E('Ionosphere combines ion with sphere; the name refers to an atmospheric region containing many ions, produced when solar radiation ionizes gases.','ionosphere'),contexts:[C('ionosphere.s1','无线电传播','The radio signal traveled beyond the horizon after reflecting from a charged layer in the ionosphere.','无线电信号从电离层中的带电层反射后，传到了地平线以外。','The radio signal traveled beyond the horizon / after reflecting / from a charged layer / in the ionosphere.','ionosphere 指大气中气体被电离、含有较多离子的区域。','带电层可影响无线电波传播。')],mistakes:[M('The diagram placed the ionosphere on the ocean floor, where sunlight ionizes seawater beneath the atmosphere.','The diagram placed the ionosphere high in the atmosphere, where solar radiation ionizes gases.','电离层位于大气中，而非海底。')],quiz:[Q('ionosphere',1,1,'The ionosphere is a region of the?','atmosphere containing many ions','ocean floor containing salt','Earth’s core made of solid iron','atmosphere containing many ions','ionosphere 是大气中富含离子的区域。'),Q('ionosphere',2,1,'What helps create ions in the ionosphere?','solar radiation ionizing gases','waves polishing ocean rocks','a city’s traffic lights','solar radiation ionizing gases','太阳辐射会使大气气体电离。'),Q('ionosphere',3,1,'The ionosphere can affect?','radio-wave propagation','the price on an invoice','the grammar of a sentence only','radio-wave propagation','电离层会影响无线电波传播。'),Q('ionosphere',4,1,'The word ionosphere combines ion and?','sphere','invoice','invigilate','sphere','该词由 ion 与 sphere 构成。','word-formation')]});
D('iridescent',{etymology:E('Iridescent is based on iris, from Greek iris “rainbow”; it describes a surface whose colors shift like a soap bubble or oil film.','iridescent'),contexts:[C('iridescent.s1','自然观察','As the beetle turned beneath the lamp, its iridescent shell shifted from green to blue and violet.','甲虫在灯下转动时，虹彩般的外壳从绿色变成蓝色和紫色。','As the beetle turned beneath the lamp / its iridescent shell shifted / from green to blue and violet.','iridescent 描述随视角或光线变化而呈现不同彩色光泽的表面。','外壳颜色随甲虫转动而变化。')],mistakes:[M('The stone was iridescent because it stayed uniformly matte gray from every angle under changing light.','The stone was iridescent because its surface shifted between blue, green, and purple as it moved.','在各种角度都保持无光灰色，不具虹彩变化。')],quiz:[Q('iridescent',1,1,'An iridescent surface shows?','colors that shift with light or angle','only one dull color in every view','a printed alphabetical list','colors that shift with light or angle','iridescent 指颜色随光线或角度变化的虹彩效果。'),Q('iridescent',2,1,'Which object might look iridescent?','a soap bubble reflecting shifting colors','a flat black card with no sheen','a plain white receipt','a soap bubble reflecting shifting colors','肥皂泡表面常出现虹彩。'),Q('iridescent',3,1,'Which description fits an iridescent shell?','it flashes green, blue, and violet as it turns','it remains uniformly brown in all light','it is completely transparent and colorless','it flashes green, blue, and violet as it turns','转动时显现多种变化颜色，符合 iridescent。'),Q('iridescent',4,1,'Iridescent is closest to?','rainbow-colored and shifting','invisible','invariable','rainbow-colored and shifting','具有变化的虹彩与该词义相近。','confusable')]});
D('iridium',{etymology:E('Iridium was named from Greek iris “rainbow,” after the striking colors of some compounds of this platinum-group metal.','iridium'),contexts:[C('iridium.s1','材料科学','The spark-plug alloy contains iridium because the metal resists heat and wear in repeated engine cycles.','这种火花塞合金含有铱，因为这种金属能耐受反复发动机循环产生的高温和磨损。','The spark-plug alloy contains iridium / because the metal resists heat and wear / in repeated engine cycles.','iridium 是铂族金属铱，化学符号为 Ir。','铱的耐热耐磨性质适用于火花塞合金。')],mistakes:[M('The lab labeled the sample iridium even though its analysis identified it as a soft alkali metal with symbol Na.','The lab labeled the sample iridium after confirming its platinum-group composition and symbol Ir.','Na 是钠的符号，不是铱；铱是铂族金属。')],quiz:[Q('iridium',1,1,'Iridium is a member of the?','platinum group of metals','alkali metals only','halogen gases','platinum group of metals','iridium 属于铂族金属。'),Q('iridium',2,1,'What is the chemical symbol for iridium?','Ir','Id','Iu','Ir','铱的元素符号为 Ir。'),Q('iridium',3,1,'Why may iridium be used in spark plugs?','it resists heat and wear','it dissolves instantly in water','it is a soft gas at room temperature','it resists heat and wear','铱耐高温和磨损，适用于火花塞材料。'),Q('iridium',4,1,'Iridium compounds helped inspire the element’s name through their?','striking colors','sweet taste','ability to float','striking colors','iridium 名称与化合物的鲜明颜色有关。')]});
D('ironic',{etymology:E('Ironic comes from irony, ultimately from Greek eironeia “feigned ignorance”; it describes either verbal mockery or an outcome opposite to what was expected.','ironic'),contexts:[C('ironic.s2','新闻评论','It was ironic that the city’s “Clean Air Day” was postponed because smoke from a nearby fire filled the square.','市里的“清洁空气日”因附近火灾的烟雾弥漫广场而延期，这一结果颇具讽刺意味。','It was ironic / that the city’s “Clean Air Day” was postponed / because smoke from a nearby fire / filled the square.','ironic.s2 指结果与预期形成反差，显得出人意料或带有反讽意味。','以清洁空气为主题的活动因烟雾而延期，形成反差。')],mistakes:[M('It was ironic that the outdoor concert happened exactly as organizers had predicted, with no surprising contrast or reversal.','It was ironic that the outdoor concert was canceled by clear weather after organizers had spent weeks preparing for rain.','没有意外反差的顺利结果不符合此处 ironic 的含义。')],quiz:[Q('ironic',1,2,'An ironic outcome is often?','the opposite of what was expected','exactly what everyone predicted','a measurement of metal hardness','the opposite of what was expected','ironic.s2 指结果与预期相反或形成反差。'),Q('ironic',2,1,'An ironic remark may?','say the opposite of what is meant to mock something','state a measurement without attitude','describe a metal alloy','say the opposite of what is meant to mock something','ironic.s1 可指用反话表达讽刺。'),Q('ironic',3,2,'Which situation is ironic?','a fire station is closed because its alarm system was never tested','a train arrives on the time printed in its schedule','a cook prepares the requested meal','a fire station is closed because its alarm system was never tested','消防站因警报系统未测试而关闭，结果与其职责反差明显。'),Q('ironic',4,1,'“Wonderful timing,” said after a bus leaves just before someone arrives, may be?','ironic','invariable','irreparable','ironic','这句话反着表达不满，属于反语。','confusable')]});
D('ironical',{etymology:E('Ironical is an adjective form of irony and is a less common alternative to ironic, especially for speech that conveys mockery through contrast.','ironical'),contexts:[C('ironical.s1','文学对话','With an ironical smile, the editor thanked the author for a “very brief” report that ran to two hundred pages.','编辑带着讽刺的微笑，感谢作者写了“一份非常简短”的报告，而它足有两百页。','With an ironical smile / the editor thanked the author / for a “very brief” report / that ran to two hundred pages.','ironical 指以反话或反差表达嘲讽，形式较 ironic 少见。','“非常简短”与两百页的长度形成嘲讽反差。')],mistakes:[M('Her ironical compliment sincerely praised the report as brief even though it contained only two pages.','Her ironical compliment called the two-hundred-page report “brief” to mock its length.','报告确实很短，赞为“简短”就没有反话讽刺。')],quiz:[Q('ironical',1,1,'An ironical compliment usually?','uses praise to convey mockery or criticism','expresses uncomplicated sincere admiration','lists the price of iron','uses praise to convey mockery or criticism','ironical 可用表面称赞来表达讽刺。'),Q('ironical',2,1,'Which sentence is ironical?','“A perfect quiet room,” she said beside a jackhammer.','“The room is quiet,” she said in a silent library.','“The wall is red,” she wrote on a color chart.','“A perfect quiet room,” she said beside a jackhammer.','在噪音旁称为安静，形成反话反差。'),Q('ironical',3,1,'Ironical is closest in meaning to?','ironic','irreparable','intuitive','ironic','ironical 是 ironic 的较少见形容词变体。','confusable'),Q('ironical',4,1,'The adjective ironical is related to the noun?','irony','ironwork','iridium','irony','ironical 描写 irony 所具有的反讽性质。','word-formation')]});
D('ironically',{etymology:E('Ironically is formed from ironic with -ly; it can describe speech that says the opposite of what is meant or a result that is unexpectedly contrary to expectation.','ironically'),contexts:[C('ironically.s2','新闻报道','Ironically, the campaign encouraging people to cycle had to move its launch indoors because every bicycle was stolen overnight.','颇具讽刺意味的是，鼓励人们骑车的活动因自行车一夜之间全被偷走，只得改在室内启动。','Ironically / the campaign encouraging people to cycle / had to move its launch indoors / because every bicycle was stolen overnight.','ironically.s2 用于引出与预期相反、带有反差的结果。','骑行活动因自行车全被偷而转入室内，形成反差。')],mistakes:[M('Ironically, the carefully predicted result occurred exactly as planned and contained no surprising contrast.','Ironically, the campaign’s bicycle display was canceled after the display bicycles disappeared overnight.','完全按预期发生且无反差，不能说明 ironically 的反差义。')],quiz:[Q('ironically',1,2,'At the start of a sentence, ironically can introduce?','an outcome contrary to what was expected','a routine result with no contrast','an exact chemical symbol','an outcome contrary to what was expected','ironically.s2 表示结果出乎预料且带反差。'),Q('ironically',2,1,'A speaker may use ironically to signal that?','the words convey mockery rather than their literal praise','the statement is a neutral measurement','the sentence is an invoice','the words convey mockery rather than their literal praise','ironically.s1 可说明话语以反语表达讽刺。'),Q('ironically',3,2,'Which event can be introduced by “Ironically”?','a fire-safety office closes after its own faulty alarm sparks panic','a planned meeting begins at its scheduled time','a lab records the expected result','a fire-safety office closes after its own faulty alarm sparks panic','消防安全办公室因自身警报故障关闭，结果颇有反差。'),Q('ironically',4,1,'“Brilliant work,” said after a careless mistake, is likely meant?','ironically','literally as a chemical description','as an invoice total','ironically','用表面称赞批评错误，属于反语。','confusable')]});
D('ironwork',{etymology:E('Ironwork combines iron with work and names objects or decorative construction made from iron, such as gates, rails, or ornamental fittings.','ironwork'),contexts:[C('ironwork.s1','建筑修复','The conservators removed layers of paint from the balcony ironwork before treating the rust and repainting the railings.','修复人员先清除阳台铁艺上的多层油漆，再处理锈迹并重新粉刷栏杆。','The conservators removed layers of paint / from the balcony ironwork / before treating the rust / and repainting the railings.','ironwork 指铁制构件或铁艺制品，通常作不可数集合名词。','栏杆等铁制建筑部件需要除锈和修复。')],mistakes:[M('The catalog listed the carved wooden door as ironwork even though no iron component was used.','The catalog listed the wrought-iron gate and railings as ironwork.','完全由木材制成的门不属于铁制品或铁艺。')],quiz:[Q('ironwork',1,1,'Ironwork consists of?','objects or structures made of iron','documents about investment','a kind of atmospheric layer','objects or structures made of iron','ironwork 指铁制品或铁艺。'),Q('ironwork',2,1,'Which item is ironwork?','a wrought-iron balcony railing','a wooden paper folder','a glass of iodine solution','a wrought-iron balcony railing','锻铁栏杆是铁艺制品。'),Q('ironwork',3,1,'A restorer treating ironwork may need to remove?','rust from a metal gate','ink from a paper invoice','ions from a sentence','rust from a metal gate','铁艺常需除锈。'),Q('ironwork',4,1,'Ironwork is usually used as a?','collective noun for iron-made objects','verb meaning to supervise an exam','plural form of iron','collective noun for iron-made objects','ironwork 通常指一类铁制构件的集合。','grammar')]});
D('irradiate',{etymology:E('Irradiate comes from Latin irradiatus, from radius “ray”; it means expose something to radiation or direct light onto it.','irradiate'),contexts:[C('irradiate.s1','食品安全','The processing plant can irradiate sealed spices to reduce harmful microbes without opening their packages.','加工厂可以对密封香料进行辐照，以减少有害微生物而不必打开包装。','The processing plant can irradiate sealed spices / to reduce harmful microbes / without opening their packages.','irradiate 指用辐射处理材料，也可指以光照射。','密封香料接受辐射处理以降低微生物。')],mistakes:[M('The plant irradiated the spices by placing them in an unlit cupboard with no radiation source or light.','The plant irradiated the spices in a controlled unit that exposed them to radiation.','没有光或辐射源的黑暗储存不是 irradiate。')],quiz:[Q('irradiate',1,1,'To irradiate packaged food is to?','expose it to radiation as a treatment','leave it in an ordinary cupboard','charge the customer an invoice','expose it to radiation as a treatment','irradiate 可指对食品进行辐照处理。'),Q('irradiate',2,1,'Which sentence uses irradiate correctly?','The laboratory irradiated the samples before testing them.','The laboratory irradiated the report by proofreading it.','The laboratory irradiated the room by locking the door.','The laboratory irradiated the samples before testing them.','irradiate 的宾语可以是接受辐照的样本。'),Q('irradiate',3,1,'The root radi in irradiate is connected with?','rays or radiation','rainbow-colored metal','backbone','rays or radiation','该词与拉丁语 radius“光线”有关。','word-formation'),Q('irradiate',4,1,'To irradiate a dark surface with a lamp can mean to?','shine light on it','make it legally invalid','turn it into an investor','shine light on it','irradiate 也可表示照亮或照射。')]});
D('irrationally',{etymology:E('Irrationally is formed from irrational with -ly; it means in a way that lacks sound reason or logical support.','irrationally'),contexts:[C('irrationally.s1','风险决策','He reacted irrationally to the small delay, canceling the entire trip before checking whether the connecting train was affected.','面对小小的延误，他反应得不理智，甚至没确认接驳列车是否受影响就取消了整个行程。','He reacted irrationally to the small delay / canceling the entire trip / before checking / whether the connecting train was affected.','irrationally 表示缺少充分理由或逻辑地作出反应。','他没有核实影响就采取了过度决定。')],mistakes:[M('She acted irrationally by comparing all available evidence calmly and choosing the option with the strongest support.','She acted irrationally by ignoring the evidence and canceling every option in panic.','冷静比较证据并选择依据最强的方案是理性行为。')],quiz:[Q('irrationally',1,1,'To react irrationally is to react?','without sound reason','after careful comparison of evidence','according to a fixed schedule','without sound reason','irrationally 指不合理地或不理智地。'),Q('irrationally',2,1,'Which response is irrational?','canceling a trip over a minor delay without checking alternatives','checking new departure times before deciding','asking whether the connection is still available','canceling a trip over a minor delay without checking alternatives','未经核实便因小延误取消行程，缺乏合理判断。'),Q('irrationally',3,1,'Irrationally is the adverb from?','irrational','iridescent','irrevocable','irrational','irrationally 由 irrational 加 -ly 构成。','word-formation'),Q('irrationally',4,1,'An irrationally high price is?','unreasonable in relation to the facts','fixed by a mathematical constant','invisible from every angle','unreasonable in relation to the facts','该副词也可修饰“不合理地高”。')]});
D('irreconcilable',{etymology:E('Irreconcilable combines ir- “not” with reconcilable, from reconcile; it describes positions so opposed that no agreement or merger is possible.','irreconcilable'),contexts:[C('irreconcilable.s1','合同谈判','The two companies had irreconcilable views on data ownership, so mediation ended without a settlement.','两家公司对数据所有权的看法无法调和，因此调解未能达成和解。','The two companies had irreconcilable views / on data ownership / so mediation ended / without a settlement.','irreconcilable 描述分歧极大、无法通过协调达成一致的立场。','谈判经调解仍未能解决两方分歧。')],mistakes:[M('The parties’ views were irreconcilable because both accepted the same terms and signed the same settlement.','The parties’ views were irreconcilable because neither would accept the other’s terms.','双方已接受相同条款并达成协议，说明分歧已调和。')],quiz:[Q('irreconcilable',1,1,'Irreconcilable differences are?','too opposed to be settled or combined','already resolved by agreement','minor preferences with no effect','too opposed to be settled or combined','irreconcilable 指无法调和的。'),Q('irreconcilable',2,1,'Which positions are irreconcilable?','one side demands full ownership while the other refuses any transfer','both sides accept the same ownership plan','both sides agree to postpone a decision','one side demands full ownership while the other refuses any transfer','核心要求互相冲突且无人让步，难以调和。'),Q('irreconcilable',3,1,'Irreconcilable is closest to?','incompatible','inviting','invariable','incompatible','incompatible 也可指不相容的。','confusable'),Q('irreconcilable',4,1,'The prefix ir- in irreconcilable contributes?','not','again','between','not','ir- 是表示否定的前缀。','word-formation')]});
D('irregularly',{etymology:E('Irregularly is formed from irregular with -ly; it describes an uneven pattern or an action that does not follow a fixed schedule.','irregularly'),contexts:[C('irregularly.s1','公交时刻','During the road repairs, buses arrived irregularly, sometimes five minutes apart and sometimes nearly an hour apart.','道路维修期间，公交车到站时间不规律，有时相隔五分钟，有时却接近一小时。','During the road repairs / buses arrived irregularly / sometimes five minutes apart / and sometimes nearly an hour apart.','irregularly 可表示形状不规则，也可表示发生时间不定期。','到站间隔变化很大，没有固定时刻。')],mistakes:[M('The buses arrived irregularly at exactly ten-minute intervals throughout the entire week.','The buses arrived irregularly at changing intervals during the road repairs.','严格保持十分钟间隔是规律运行，不是 irregularly。')],quiz:[Q('irregularly',1,1,'If trains arrive irregularly, they arrive?','at uneven or unpredictable times','at exactly fixed intervals','only on a written invoice','at uneven or unpredictable times','irregularly 表示不定期或不规律地。'),Q('irregularly',2,1,'An irregularly shaped stone has?','an uneven outline','a perfectly smooth circle','a constant chemical charge','an uneven outline','该词也可描述形状不规则。'),Q('irregularly',3,1,'Choose the adverb: “The clinic is ___ open on Saturdays.”','irregularly','irregular','irregularity','irregularly','修饰 open 需要副词 irregularly。','word-formation'),Q('irregularly',4,1,'Which pattern is irregular?','deliveries occur on changing days with no set interval','a bell rings every hour on the hour','a light flashes at precisely one-second intervals','deliveries occur on changing days with no set interval','没有固定间隔的配送属于 irregular。')]});
D('irrelevant',{etymology:E('Irrelevant combines ir- “not” with relevant, from Latin relevare “to raise”; it means having no useful connection with the matter being considered.','irrelevant'),contexts:[C('irrelevant.s1','招聘面试','The candidate’s childhood stamp collection was irrelevant to the engineering role, so the panel focused on her technical experience.','候选人童年集邮与工程岗位无关，因此面试小组把重点放在她的技术经验上。','The candidate’s childhood stamp collection / was irrelevant to the engineering role / so the panel focused / on her technical experience.','irrelevant 表示与当前问题、任务或判断没有有用关联。','招聘小组应关注技术能力，而不是无关的童年爱好。')],mistakes:[M('The engineer called the failed safety test irrelevant even though the meeting was specifically deciding whether the device was safe.','The engineer called the unrelated color preference irrelevant to the safety decision.','安全测试与安全决策直接相关，不能称为无关。')],quiz:[Q('irrelevant',1,1,'Information is irrelevant when it?','has no useful connection to the matter','directly answers the question','provides essential evidence','has no useful connection to the matter','irrelevant 指与当前事项无关。'),Q('irrelevant',2,1,'In a hiring decision for an engineer, which fact is likely irrelevant?','the candidate’s favorite childhood cartoon','her experience designing bridges','her ability to use engineering software','the candidate’s favorite childhood cartoon','童年喜欢的动画通常与工程胜任能力无关。'),Q('irrelevant',3,1,'Which sentence uses irrelevant correctly?','That detail is irrelevant to the cause of the accident.','The evidence is irrelevant because it directly explains the cause.','The rule is irrelevant to the issue because it governs that exact issue.','That detail is irrelevant to the cause of the accident.','该细节与事故原因无关时才适用 irrelevant。'),Q('irrelevant',4,1,'Irrelevant is the opposite of?','relevant','iridescent','irresolute','relevant','relevant 表示相关的，与 irrelevant 相反。','confusable')]});
D('irreparable',{etymology:E('Irreparable combines ir- “not” with repairable, from repair; it describes harm or damage that cannot be repaired or undone.','irreparable'),contexts:[C('irreparable.s1','档案保护','The flood caused irreparable damage to several handwritten letters before the conservators could move them.','在修复人员来得及转移之前，洪水已对几封手写信件造成无法挽回的损害。','The flood caused irreparable damage / to several handwritten letters / before the conservators / could move them.','irreparable 指无法修复或挽回的损害。','纸张严重受损，修复人员无法恢复原状。')],mistakes:[M('The scratch caused irreparable damage even though a simple polish removed it completely and restored the original surface.','The chemical burn caused irreparable damage because the original surface could not be restored.','已完全修复的轻微划痕不是无法挽回的损害。')],quiz:[Q('irreparable',1,1,'Irreparable damage is damage that?','cannot be repaired or undone','can be removed with a quick polish','has not yet occurred','cannot be repaired or undone','irreparable 指无法修复或挽回的。'),Q('irreparable',2,1,'Which loss is irreparable?','a unique manuscript destroyed beyond recovery','a torn page that was fully restored','a delayed package that later arrived','a unique manuscript destroyed beyond recovery','唯一手稿彻底毁坏后无法恢复。'),Q('irreparable',3,1,'The prefix ir- in irreparable means?','not','again','before','not','此处 ir- 表否定。','word-formation'),Q('irreparable',4,1,'Irreparable is closest to?','beyond repair','temporary','inviting','beyond repair','beyond repair 与 irreparable 意思相近。','confusable')]});
D('irrepressible',{etymology:E('Irrepressible combines ir- “not” with repressible from repress; it describes energy, emotion, or a person too strong or lively to be held back.','irrepressible'),contexts:[C('irrepressible.s1','人物描写','Even after the long rehearsal, the children’s irrepressible excitement spilled into laughter as the curtain rose.','即使经过漫长排练，幕布升起时孩子们仍按捺不住兴奋，笑声不断。','Even after the long rehearsal / the children’s irrepressible excitement / spilled into laughter / as the curtain rose.','irrepressible 形容无法压抑或阻挡的活力、情绪或表现。','孩子们的兴奋强烈到无法平静下来。')],mistakes:[M('Her irrepressible laughter was easy to suppress; she stopped instantly whenever anyone asked her to.','Her irrepressible laughter continued despite repeated attempts to quiet the room.','轻易就能停止的笑声不符合“难以压抑”的意思。')],quiz:[Q('irrepressible',1,1,'Irrepressible excitement is excitement that?','is too strong to be held back','has already disappeared','is carefully hidden from everyone','is too strong to be held back','irrepressible 指难以抑制的。'),Q('irrepressible',2,1,'Which child seems irrepressible?','one who keeps bursting into delighted laughter','one who quietly follows every instruction','one who feels no interest in the event','one who keeps bursting into delighted laughter','持续兴奋欢笑显示难以压抑的活力。'),Q('irrepressible',3,1,'Irrepressible is closest to?','uncontainable','irrelevant','irrevocable','uncontainable','uncontainable 同样表示难以控制的。','confusable'),Q('irrepressible',4,1,'The prefix ir- in irrepressible means?','not','again','under','not','该前缀表示否定。','word-formation')]});
D('irreproachable',{etymology:E('Irreproachable combines ir- “not” with reproachable, from reproach; it describes conduct or work that cannot fairly be criticized.','irreproachable'),contexts:[C('irreproachable.s1','职业操守','The audit found the treasurer’s record irreproachable: every payment had a receipt and two independent approvals.','审计发现财务主管的记录无可指责：每笔付款都有收据和两项独立批准。','The audit found the treasurer’s record irreproachable / every payment had a receipt / and two independent approvals.','irreproachable 表示在行为、品味或表现方面无可非议。','凭证齐全且经过独立审批，没有发现可指责之处。')],mistakes:[M('The committee called the record irreproachable despite missing receipts, unexplained transfers, and a proven forged signature.','The committee called the record irreproachable after verifying every payment and approval.','多项缺失与伪造证据足以构成明确过失。')],quiz:[Q('irreproachable',1,1,'An irreproachable record is?','free from faults that can fairly be criticized','full of unexplained errors','impossible to read','free from faults that can fairly be criticized','irreproachable 表示无可指责的。'),Q('irreproachable',2,1,'Which conduct is irreproachable?','reporting every expense accurately and retaining receipts','hiding transfers from an auditor','forging an approval signature','reporting every expense accurately and retaining receipts','如实报告并留存凭证的行为无可非议。'),Q('irreproachable',3,1,'Irreproachable is closest to?','blameless','irresolute','invasive','blameless','blameless 同样表示无可指责的。','confusable'),Q('irreproachable',4,1,'The prefix ir- in irreproachable means?','not','very','between','not','ir- 是否定前缀。','word-formation')]});
D('irresistible',{etymology:E('Irresistible combines ir- “not” with resistible from resist; it describes something too powerful or attractive to refuse or withstand.','irresistible'),contexts:[C('irresistible.s1','甜品广告','The bakery’s warm apple tart, served with cinnamon cream, proved irresistible to the guests.','面包店端上的温热苹果挞配肉桂奶油，让客人们难以抗拒。','The bakery’s warm apple tart / served with cinnamon cream / proved irresistible / to the guests.','irresistible 描述强烈到难以抵抗或拒绝的吸引力。','甜点的味道和香气让客人无法拒绝。')],mistakes:[M('The offer was irresistible even though every customer refused it immediately and no one found it appealing.','The offer was irresistible because its generous terms persuaded nearly everyone to accept.','人人立即拒绝且无人觉得有吸引力，不符合 irresistible。')],quiz:[Q('irresistible',1,1,'An irresistible offer is one that?','is very hard to refuse','has no appeal to anyone','is legally invalid','is very hard to refuse','irresistible 指难以拒绝或抗拒的。'),Q('irresistible',2,1,'Which smell might be irresistible to hungry visitors?','fresh bread just out of the oven','an empty clean plate','a closed cupboard with no food','fresh bread just out of the oven','刚出炉面包的香气对饥饿的人很有吸引力。'),Q('irresistible',3,1,'Irresistible is closest to?','impossible to resist','unable to make a decision','impossible to repair','impossible to resist','impossible to resist 是 irresistible 的释义。'),Q('irresistible',4,1,'If a force is irresistible, it?','cannot be successfully opposed','is easy to stop','never has any effect','cannot be successfully opposed','该词也可描述强大到无法抗衡的力量。')]});
D('irresolute',{etymology:E('Irresolute combines ir- “not” with resolute, from resolve; it describes someone unable to make or maintain a firm decision.','irresolute'),contexts:[C('irresolute.s1','团队决策','The manager remained irresolute between the two suppliers and delayed signing either contract for another month.','经理在两家供应商之间犹豫不决，又把两份合同都拖延了一个月。','The manager remained irresolute / between the two suppliers / and delayed signing / either contract for another month.','irresolute 指作决定时缺少坚定态度、优柔寡断的。','经理无法在两家供应商中作出决定。')],mistakes:[M('She was irresolute about the venue because she chose one immediately and never reconsidered it.','She was irresolute about the venue because she kept changing her mind and postponed the choice.','迅速作出并坚持决定不体现犹豫不决。')],quiz:[Q('irresolute',1,1,'An irresolute person is?','uncertain and unable to decide firmly','decisive and confident','impossible to persuade','uncertain and unable to decide firmly','irresolute 指优柔寡断的。'),Q('irresolute',2,1,'Which behavior seems irresolute?','switching between two choices without deciding','choosing a supplier and signing the contract','rejecting both choices for a clear reason','switching between two choices without deciding','反复摇摆而不作决定表现出犹豫。'),Q('irresolute',3,1,'Irresolute is the opposite of?','resolute','irreparable','iridescent','resolute','resolute 表示果断坚定，与 irresolute 相反。','confusable'),Q('irresolute',4,1,'Which word completes the sentence: “She was too ___ to give a firm answer”?','irresolute','irreproachable','iridescent','irresolute','无法坚定作答说明她犹豫不决。')]});
D('irresponsibly',{etymology:E('Irresponsibly is formed from irresponsible with -ly; it describes acting without proper care for duties or likely consequences.','irresponsibly'),contexts:[C('irresponsibly.s1','公共安全','The contractor acted irresponsibly by removing the barrier before the wet floor had dried and visitors had left.','承包商在湿地面尚未干、访客尚未离开前就撤掉护栏，行为不负责任。','The contractor acted irresponsibly / by removing the barrier / before the wet floor had dried / and visitors had left.','irresponsibly 表示不顾职责或可能危害地行事。','撤掉湿滑区域的护栏会让访客面临可预见风险。')],mistakes:[M('The nurse behaved irresponsibly by checking the patient’s identity twice, following the dosage chart, and documenting the medicine.','The nurse behaved irresponsibly by skipping the identity check and giving an unverified dose.','核对身份、遵循剂量表并记录用药是负责任的做法。')],quiz:[Q('irresponsibly',1,1,'To act irresponsibly is to act?','without proper care for duties or consequences','with careful attention to safety','according to a verified procedure','without proper care for duties or consequences','irresponsibly 指不负责任地行事。'),Q('irresponsibly',2,1,'Which action is irresponsible?','removing a warning barrier while a floor is still wet','testing the floor before reopening it','keeping visitors away from a hazard','removing a warning barrier while a floor is still wet','湿地面未干就撤除警示会造成风险。'),Q('irresponsibly',3,1,'Irresponsibly is the adverb from?','irresponsible','irreverent','irreversible','irresponsible','irresponsibly 由 irresponsible 加 -ly 构成。','word-formation'),Q('irresponsibly',4,1,'Ignoring a clear safety warning is acting?','irresponsibly','irreproachably','iridescently','irresponsibly','不顾明确安全警告属于不负责任。')]});
D('irreverence',{etymology:E('Irreverence combines ir- “not” with reverence, from Latin revereri “to stand in awe of”; it means a refusal to show expected solemn respect, sometimes humorously.','irreverence'),contexts:[C('irreverence.s1','校园演讲','The speaker’s irreverence toward the school’s ceremonial rules drew laughter from students and a frown from the principal.','演讲者对学校仪式规则的戏谑不敬逗笑了学生，却让校长皱起眉头。','The speaker’s irreverence toward the school’s ceremonial rules / drew laughter from students / and a frown / from the principal.','irreverence 指不按通常要求表示庄重敬意的态度，有时带幽默意味。','学生觉得玩笑有趣，而校长认为仪式应受尊重。')],mistakes:[M('The audience praised the speech’s irreverence because it followed every solemn convention and made no joke or challenge.','The audience noticed the speech’s irreverence when it joked about the ceremony’s most solemn rule.','完全遵守仪式且没有戏谑，不体现不敬或轻慢。')],quiz:[Q('irreverence',1,1,'Irreverence is an attitude that?','withholds the respect usually shown to something solemn','shows deep formal respect','measures the charge of an ion','withholds the respect usually shown to something solemn','irreverence 指对庄严事物不够尊重的态度。'),Q('irreverence',2,1,'Which comment shows irreverence at a solemn ceremony?','a playful joke about the strict ceremonial script','a respectful thank-you to the officiant','a quiet request for directions','a playful joke about the strict ceremonial script','拿严肃仪式脚本开玩笑体现轻慢。'),Q('irreverence',3,1,'Irreverence is the noun related to?','irreverent','iridescent','irreparable','irreverent','irreverence 是 irreverent 的名词形式。','word-formation'),Q('irreverence',4,1,'Irreverence may be humorous, but it can also be?','offensive to people who expect solemn respect','a type of chemical treatment','a fixed schedule','offensive to people who expect solemn respect','不敬有时会冒犯重视庄严的人。')]});
D('irreverent',{etymology:E('Irreverent combines ir- “not” with reverent; it describes speech or behavior that does not show the expected respect for serious matters.','irreverent'),contexts:[C('irreverent.s1','文化评论','The irreverent cartoon portrayed the mayor as a sleepy cat during a debate about the city’s solemn anniversary.','在讨论城市庄严周年纪念时，这幅不拘礼数的漫画把市长画成一只打瞌睡的猫。','The irreverent cartoon portrayed the mayor / as a sleepy cat / during a debate / about the city’s solemn anniversary.','irreverent 描述对严肃人物、仪式或观念缺少通常敬意的言行。','漫画用滑稽形象消解正式纪念活动的庄重感。')],mistakes:[M('The ceremony was irreverent because every speaker used formal titles, observed silence, and followed the solemn script.','The ceremony became irreverent when a speaker mocked the formal titles and turned the tribute into a joke.','庄重遵守仪式规范与 irreverent 的不敬相反。')],quiz:[Q('irreverent',1,1,'An irreverent joke treats a serious subject?','without the usual respect','with solemn formality','as a chemical element','without the usual respect','irreverent 指对严肃事物不够尊重的。'),Q('irreverent',2,1,'Which speaker sounds irreverent?','one who jokes about a solemn memorial','one who observes a moment of silence','one who thanks the families formally','one who jokes about a solemn memorial','在纪念仪式上开玩笑显得不够庄重。'),Q('irreverent',3,1,'Irreverent is closest to?','disrespectful','irreproachable','inviting','disrespectful','disrespectful 与 irreverent 意义接近。','confusable'),Q('irreverent',4,1,'The adjective irreverent is related to the noun?','irreverence','iridium','invariance','irreverence','irreverent 与 irreverence 是形容词和名词关系。','word-formation')]});
D('irreversible',{etymology:E('Irreversible combines ir- “not” with reversible from reverse; it describes a change that cannot be turned back once it has occurred.','irreversible'),contexts:[C('irreversible.s1','生态恢复','Once the hillside’s topsoil was washed into the reservoir, the loss proved irreversible within the project’s time frame.','山坡表土一旦被冲入水库，在该项目的时间范围内，这种损失便无法逆转。','Once the hillside’s topsoil was washed into the reservoir / the loss proved irreversible / within the project’s time frame.','irreversible 指发生后不能逆转或恢复原状的。','表土流失后无法在项目期限内恢复。')],mistakes:[M('The change was irreversible because the technician restored the original settings with one click and no lasting effect remained.','The change was irreversible because the damaged data could not be restored from any backup.','轻松恢复且无持久影响，说明该变化可逆。')],quiz:[Q('irreversible',1,1,'An irreversible change?','cannot be turned back to its former state','is easy to undo','has not yet begun','cannot be turned back to its former state','irreversible 指不可逆转的。'),Q('irreversible',2,1,'Which event is irreversible?','the permanent loss of a one-of-a-kind record with no copy','changing a setting that can be restored','moving a chair and then moving it back','the permanent loss of a one-of-a-kind record with no copy','唯一记录永久丢失且无备份，无法恢复。'),Q('irreversible',3,1,'The prefix ir- in irreversible means?','not','again','around','not','ir- 表示否定。','word-formation'),Q('irreversible',4,1,'Irreversible is the opposite of?','reversible','irresolute','iridescent','reversible','reversible 意为可逆的，与 irreversible 相反。','confusable')]});
D('irrevocable',{etymology:E('Irrevocable combines ir- “not” with revocable, from revoke; it describes a decision, agreement, or right that cannot be withdrawn or undone.','irrevocable'),contexts:[C('irrevocable.s1','法律文件','After the transfer became irrevocable, the donor could no longer reclaim the funds under the agreement.','转让变为不可撤销后，捐赠人便不能再依据协议收回资金。','After the transfer became irrevocable / the donor could no longer reclaim the funds / under the agreement.','irrevocable 常形容一旦生效便不能撤回或取消的决定、协议或权利。','协议生效后捐赠人不能取回资金。')],mistakes:[M('The instruction was irrevocable even though the signer canceled it freely the next morning without anyone’s consent.','The instruction was irrevocable because the signed agreement did not permit later withdrawal.','签署人可以随意取消，说明指示并非不可撤销。')],quiz:[Q('irrevocable',1,1,'An irrevocable agreement cannot be?','withdrawn or canceled once effective','read by either party','written in ink','withdrawn or canceled once effective','irrevocable 指不可撤销的。'),Q('irrevocable',2,1,'Which decision is irrevocable?','a final transfer that the contract forbids reclaiming','a booking that can be canceled for free','a draft that has not been approved','a final transfer that the contract forbids reclaiming','合同禁止收回的最终转让是不可撤销的。'),Q('irrevocable',3,1,'Irrevocable is most closely related to the verb?','revoke','irrigate','irradiate','revoke','irrevocable 表示不能被 revoke（撤销）。','word-formation'),Q('irrevocable',4,1,'Which adjective is closest to irrevocable?','final and not withdrawable','temporary and reversible','confusing but optional','final and not withdrawable','不可撤销的决定通常不可收回。','confusable')]});
D('irrigation',{etymology:E('Irrigation comes from Latin irrigare “to water,” from in- and rigare “to wet”; it means supplying water to land or washing a wound with flowing liquid.','irrigation'),contexts:[C('irrigation.s2','伤口护理','The nurse used sterile irrigation to rinse grit from the cut before applying a dressing.','护士在包扎前用无菌冲洗液清洗伤口中的砂砾。','The nurse used sterile irrigation / to rinse grit from the cut / before applying a dressing.','irrigation.s2 指用流动液体冲洗伤口或身体部位。','液体流过伤口以冲出异物，属于医学冲洗。')],mistakes:[M('The nurse described irrigation as drying the wound with warm air while no liquid touched the injured area.','The nurse described irrigation as flushing the wound with sterile fluid.','没有液体冲洗时不属于医学意义的 irrigation。')],quiz:[Q('irrigation',1,1,'Agricultural irrigation supplies water to?','land or crops','a magazine issue','a metal alloy','land or crops','irrigation.s1 指给土地或作物供水。'),Q('irrigation',2,2,'Medical irrigation is used to?','wash a wound or body part with flowing liquid','seal a wound without cleaning it','measure an isotope’s age','wash a wound or body part with flowing liquid','irrigation.s2 指用液体冲洗身体部位。'),Q('irrigation',3,2,'Which action is wound irrigation?','flushing grit from a cut with sterile fluid','covering the cut without rinsing','checking the dressing color','flushing grit from a cut with sterile fluid','用无菌液冲出砂砾是冲洗伤口。'),Q('irrigation',4,1,'A farmer planning irrigation is deciding how to?','water fields or crops','issue a permit','isolate an isotope','water fields or crops','农业灌溉的目的是为土地或作物供水。')]});
D('irritability',{etymology:E('Irritability is formed from irritable with -ity and names a tendency to become annoyed easily; in technical use it can also describe responsiveness to stimulation.','irritability'),contexts:[C('irritability.s1','人物观察','Lack of sleep increased his irritability, so even a small delay in the meeting made him snap at his colleagues.','睡眠不足使他更容易烦躁，因此会议稍有延迟就让他冲同事发火。','Lack of sleep increased his irritability / so even a small delay / in the meeting / made him snap at his colleagues.','irritability 指容易因小事恼火或不耐烦的倾向。','小小延误就引发强烈烦躁，说明他易怒。')],mistakes:[M('Her irritability was obvious because she stayed patient through repeated interruptions and never showed annoyance.','Her irritability was obvious when repeated interruptions made her answer sharply.','始终耐心且不恼火，不符合易怒倾向。')],quiz:[Q('irritability',1,1,'Irritability is a tendency to?','be annoyed by small things','make decisions that cannot be revoked','show shifting colors','be annoyed by small things','irritability 指容易烦躁的倾向。'),Q('irritability',2,1,'Which behavior may reveal irritability?','snapping at a coworker over a minor delay','waiting calmly through a long queue','thanking someone for a correction','snapping at a coworker over a minor delay','因小延误就发火体现易怒。'),Q('irritability',3,1,'Irritability is the noun related to?','irritable','irrigate','iridescent','irritable','irritability 由 irritable 派生。','word-formation'),Q('irritability',4,1,'If rest reduces someone’s irritability, that person becomes?','less easily annoyed','more difficult to repair','more likely to irrigate crops','less easily annoyed','易怒程度下降就是不那么容易烦躁。')]});
D('irritable',{etymology:E('Irritable comes from Latin irritabilis, from irritare “to excite or provoke”; it describes someone easily angered or a body part unusually sensitive.','irritable'),contexts:[C('irritable.s2','医疗问诊','The patient’s irritable skin became red and itchy after contact with the detergent, so the clinician recommended avoiding it.','患者接触洗涤剂后皮肤发红发痒，变得容易受刺激，因此医生建议避免使用。','The patient’s irritable skin became red and itchy / after contact with the detergent / so the clinician recommended avoiding it.','irritable.s2 描述器官或身体组织异常敏感、容易受刺激的状态。','皮肤接触洗涤剂后迅速发红发痒，表现为敏感。')],mistakes:[M('The skin was irritable because it never reacted to the detergent and remained comfortable after repeated exposure.','The skin was irritable because it became red and itchy after brief contact with the detergent.','完全没有反应与异常敏感相反。')],quiz:[Q('irritable',1,1,'An irritable person becomes angry?','very easily','only after careful deliberation','never under any circumstances','very easily','irritable.s1 指容易发怒的。'),Q('irritable',2,2,'An irritable organ or tissue is?','abnormally sensitive to stimulation','unusually hard to repair','permanently invisible','abnormally sensitive to stimulation','irritable.s2 描述身体部位异常敏感。'),Q('irritable',3,2,'Which symptom suggests irritable skin?','it turns red and itchy after mild contact','it never reacts to any substance','it becomes an isotope','it turns red and itchy after mild contact','轻微接触即红痒说明皮肤容易受刺激。'),Q('irritable',4,1,'Which person is irritable?','someone who gets annoyed by small setbacks','someone who remains calm through every delay','someone who monitors a jail','someone who gets annoyed by small setbacks','小事便烦恼的人容易发怒。')]});
D('irritating',{etymology:E('Irritating is the present participle of irritate and an adjective for something that causes annoyance or physical soreness and itching.','irritating'),contexts:[C('irritating.s2','实验室防护','The cleaning vapor was irritating to the eyes, so staff opened the ventilation system and put on protective goggles.','清洁剂蒸气刺激眼睛，因此工作人员打开通风系统并戴上了防护眼镜。','The cleaning vapor was irritating to the eyes / so staff opened the ventilation system / and put on protective goggles.','irritating.s2 表示导致身体部位疼痛、发痒或不适的刺激性。','蒸气让眼睛不舒服，需要通风和防护。')],mistakes:[M('The vapor was irritating to the eyes because everyone exposed to it reported no redness, itching, or discomfort.','The vapor was irritating to the eyes because it caused redness and burning.','没有不适反应的蒸气不支持“刺激眼睛”的描述。')],quiz:[Q('irritating',1,1,'An irritating comment makes someone feel?','annoyed','invincible','isolated by disease','annoyed','irritating.s1 指令人恼火的。'),Q('irritating',2,2,'An irritating substance may cause?','itching or soreness','a legal transfer','an invariable schedule','itching or soreness','irritating.s2 指造成身体刺激不适的。'),Q('irritating',3,2,'Which situation involves something irritating to the eyes?','smoke makes the eyes sting and water','a quiet room has comfortable lighting','a visitor reads a printed itinerary','smoke makes the eyes sting and water','烟雾使眼睛刺痛流泪，属于刺激。'),Q('irritating',4,1,'Choose the adjective: “The repeated alarm was ___.”','irritating','irritation','irritate','irritating','修饰 alarm 需要形容词 irritating。','word-formation')]});
D('irritation',{etymology:E('Irritation is formed from irritate with -ation; it can name mild anger or a painful, itchy reaction in tissue.','irritation'),contexts:[C('irritation.s2','皮肤护理','The bandage adhesive caused irritation around the edges of the wound, so the nurse switched to a gentler dressing.','绷带胶在伤口边缘引起刺激不适，因此护士换用了更温和的敷料。','The bandage adhesive caused irritation / around the edges of the wound / so the nurse switched / to a gentler dressing.','irritation.s2 指皮肤或身体组织出现的疼痛、发痒等刺激反应。','胶黏剂使伤口周围皮肤不适，换用温和敷料。')],mistakes:[M('The adhesive caused no irritation because the skin became red, itchy, and painful wherever it touched.','The adhesive caused irritation because the contact area became red and itchy.','红痒疼痛正是组织刺激反应，不能说没有 irritation。')],quiz:[Q('irritation',1,1,'Irritation can mean a feeling of?','mild anger or impatience','complete confidence','unusual rainbow coloring','mild anger or impatience','irritation.s1 指恼怒或不耐烦。'),Q('irritation',2,2,'Skin irritation may involve?','redness, itching, or soreness','an irrevocable agreement','a change in word order','redness, itching, or soreness','irritation.s2 指皮肤发红、瘙痒或疼痛等反应。'),Q('irritation',3,2,'Which product caused physical irritation?','a soap that left the user’s skin itchy','a book that made the reader impatient','a route that changed the schedule','a soap that left the user’s skin itchy','肥皂导致皮肤瘙痒，属于身体刺激。'),Q('irritation',4,1,'Which sentence uses irritation as annoyance?','To her irritation, the meeting began forty minutes late.','The cream relieved the skin irritation.','The nurse checked the wound for irritation.','To her irritation, the meeting began forty minutes late.','此处指延误令她恼怒。')]});
D('islander',{etymology:E('Islander is formed from island with the agent or inhabitant suffix -er and means someone whose home is an island.','islander'),contexts:[C('islander.s1','海岛社区','As an islander, Tomas knew which footpaths stayed above the tide and which boats could reach the clinic in winter.','作为岛上居民，托马斯知道哪些小路高于潮位，也知道冬季哪些船能到达诊所。','As an islander / Tomas knew which footpaths stayed above the tide / and which boats could reach the clinic / in winter.','islander 指以岛屿为家的人，不一定是游客或船员。','托马斯熟悉岛上潮汐路线和冬季交通，体现本地生活经验。')],mistakes:[M('The tourist was called an islander simply because he spent one afternoon visiting the island and lived on the mainland.','The resident who had made the island her home was described as an islander.','短暂来访而不居住岛上，通常不称为 islander。')],quiz:[Q('islander',1,1,'An islander is someone who?','lives on an island','visits an island once','works only on a mainland train','lives on an island','islander 指岛上居民。'),Q('islander',2,1,'Which person is most clearly an islander?','a resident whose home is a small island','a tourist on a day trip','a sailor passing the coast','a resident whose home is a small island','以小岛为家的人是 islander。'),Q('islander',3,1,'Islander is formed from island plus?','-er','-less','-hood','-er','-er 可构成表示居民或人的名词。','word-formation'),Q('islander',4,1,'A local islander may know?','which paths are flooded by the tide','how to issue an invoice','the number of isotopes by sight','which paths are flooded by the tide','熟悉潮汐淹路属于岛上生活经验。')]});
D('islet',{etymology:E('Islet comes from isle with the diminutive suffix -let; it means a very small island.','islet'),contexts:[C('islet.s1','航海地图','The chart marks a rocky islet just offshore, too small for permanent homes but large enough for seabirds to nest.','海图标出近海的一座岩石小岛，它小到无法长期居住，却足够让海鸟筑巢。','The chart marks a rocky islet / just offshore / too small for permanent homes / but large enough for seabirds to nest.','islet 指面积很小的小岛。','岩石岛屿面积有限，没有常住人口。')],mistakes:[M('The atlas called the large island with several cities and an airport an islet.','The atlas called the tiny uninhabited rock outcrop an islet.','有多座城市和机场的大岛不属于 islet。')],quiz:[Q('islet',1,1,'An islet is?','a very small island','a deep inland lake','a type of jailer','a very small island','islet 指小岛。'),Q('islet',2,1,'Which landform is an islet?','a tiny rocky patch surrounded by sea','a continent with several nations','a hill far from any water','a tiny rocky patch surrounded by sea','被海水围绕的小块陆地是 islet。'),Q('islet',3,1,'The suffix -let in islet suggests?','smallness','a person who lives there','a legal document','smallness','-let 常表示小型事物。','word-formation'),Q('islet',4,1,'A map might label an islet near?','the coast','the center of a desert','the roof of an office','the coast','小岛通常在海岸附近或水域中。')]});
D('isolation',{etymology:E('Isolation is formed from isolate, ultimately from Latin insula “island”; it names separation for health, the state of being apart, or the act of separating something for study or safety.','isolation'),contexts:[C('isolation.s3','实验室安全','The lab kept the unknown chemical in isolation from other samples until its properties had been identified.','在确认性质之前，实验室将这种未知化学物质与其他样品隔离存放。','The lab kept the unknown chemical in isolation / from other samples / until its properties / had been identified.','isolation.s3 指为研究或安全起见把某物单独分离出来。','未知物质被单独保存，以避免与其他样品混合。')],mistakes:[M('The lab stored the unknown chemical in isolation by pouring it into the same open container as every other sample.','The lab stored the unknown chemical in isolation in a separate sealed container.','与其他样品混在同一容器中，不构成分离保存。')],quiz:[Q('isolation',1,1,'Medical isolation may separate?','sick people from healthy people to limit infection','two pages in a magazine','two opposite ions in a crystal','sick people from healthy people to limit infection','isolation.s1 可指防疫隔离。'),Q('isolation',2,2,'A person experiencing isolation may feel?','alone or cut off from others','surrounded by close companions','unable to reverse a chemical reaction','alone or cut off from others','isolation.s2 指孤立、隔绝的状态。'),Q('isolation',3,3,'A scientist may use isolation to?','separate one sample for study or safety','make every sample identical','print a magazine issue','separate one sample for study or safety','isolation.s3 指为研究或安全而分离事物。'),Q('isolation',4,3,'Keeping a reactive chemical in its own sealed cabinet is?','isolation','irritability','irony','isolation','单独存放该物质属于分离隔离。')]});
D('isotope',{etymology:E('Isotope combines Greek isos “equal” and topos “place”; isotopes occupy the same place in the periodic table because they are forms of the same element with different neutron counts.','isotope'),contexts:[C('isotope.s2','考古测年','Researchers compared the proportions of two carbon isotopes in the sample to estimate when the organic material formed.','研究人员比较样本中两种碳同位素的比例，以估算有机材料形成的时间。','Researchers compared the proportions / of two carbon isotopes in the sample / to estimate / when the organic material formed.','isotope.s2 指可用于测年或追踪过程的同位素。','不同碳同位素比例可帮助推断材料年代。')],mistakes:[M('The chemist called two atoms isotopes even though they belonged to different elements and had different proton counts.','The chemist called the atoms isotopes because they had the same proton count but different neutron counts.','同位素属于同一元素，质子数相同而中子数不同。')],quiz:[Q('isotope',1,1,'Isotopes of one element have the same number of?','protons but different numbers of neutrons','neutrons but different numbers of protons','electrons and always identical mass numbers','protons but different numbers of neutrons','isotope.s1 的核心区别是质子数相同、中子数不同。'),Q('isotope',2,2,'A radioactive isotope may help researchers?','date an object or trace a process','write an itinerary','measure a person’s irritability','date an object or trace a process','isotope.s2 可用于测年或示踪。'),Q('isotope',3,1,'Which pair consists of isotopes of the same element?','atoms with equal proton counts and unequal neutron counts','atoms with different proton counts and equal charge','two atoms with different chemical symbols','atoms with equal proton counts and unequal neutron counts','同元素的同位素质子数相同而中子数不同。'),Q('isotope',4,2,'A tracer isotope is useful because it can?','reveal where a substance moves','make a legal decision irrevocable','turn a field into an islet','reveal where a substance moves','示踪同位素可显示物质的移动路径。')]});
D('isotopic',{etymology:E('Isotopic is formed from isotope with -ic and means relating to isotopes, especially atoms of the same element that differ in mass.','isotopic'),contexts:[C('isotopic.s1','地球化学','The researchers compared the isotopic composition of the water to distinguish rainfall from ancient groundwater.','研究人员比较水的同位素组成，以区分雨水和古地下水。','The researchers compared the isotopic composition of the water / to distinguish rainfall / from ancient groundwater.','isotopic 描述与同位素或同位素组成有关的。','不同水源的同位素比例可能不同，可用于辨别来源。')],mistakes:[M('The report called the samples isotopic even though it compared only their labels and measured no isotope or atomic mass.','The report compared the samples’ isotopic composition by measuring their isotope ratios.','没有测量同位素或相关比例，不能据此称其为同位素组成分析。')],quiz:[Q('isotopic',1,1,'Isotopic composition concerns?','the isotopes present in a material','the layout of a magazine issue','the route on a travel itinerary','the isotopes present in a material','isotopic 指与同位素组成有关。'),Q('isotopic',2,1,'An isotopic analysis may compare?','ratios of atoms of the same element with different masses','the colors of unrelated stones','the number of people on an island','ratios of atoms of the same element with different masses','同位素分析常比较同元素不同质量原子的比例。'),Q('isotopic',3,1,'Isotopic is formed from which noun?','isotope','islet','issue','isotope','isotopic 由 isotope 加 -ic 构成。','word-formation'),Q('isotopic',4,1,'A study of isotopic water signatures may help identify?','where the water came from','who issued a bill','why an exam was invigilated','where the water came from','同位素特征可帮助追踪水源。')]});
D('issue',{etymology:E('Issue comes through Anglo-French from Latin exire “to go out”; it can mean a topic or problem, one edition of a periodical, or the act of officially releasing something.','issue'),contexts:[C('issue.s3','政府公告','The agency will issue updated travel guidance as soon as the road inspection is complete.','道路检查一结束，该机构就会正式发布更新后的出行指南。','The agency will issue updated travel guidance / as soon as / the road inspection / is complete.','issue.s3 作动词，表示正式发布、签发或提供文件与信息。','政府机构将在检查完成后正式发布指南。')],mistakes:[M('The agency issued the travel guidance by keeping it private and refusing to release it to the public.','The agency issued the travel guidance by publishing it on its official site.','拒绝发布与正式发布信息相反。')],quiz:[Q('issue',1,1,'An issue for public discussion is?','an important subject or problem','a small island','a chemical element','an important subject or problem','issue.s1 指需要讨论或处理的问题。'),Q('issue',2,2,'The latest issue of a magazine is?','one particular edition','an unresolved legal transfer','a field irrigation system','one particular edition','issue.s2 指杂志或报纸的一期。'),Q('issue',3,3,'To issue an official permit is to?','formally release or provide it','hide it from its recipient','make it impossible to revoke','formally release or provide it','issue.s3 作动词表示正式签发。'),Q('issue',4,1,'A debate about housing is an issue because it is?','a subject or problem people need to address','a single magazine edition','a type of isotope','a subject or problem people need to address','住房是需要讨论和处理的议题。')]});
D('Italian',{etymology:E('Italian is formed from Italy with the suffix -an and can name a person or the Romance language, or describe something relating to Italy.','Italian'),contexts:[C('Italian.s2','文化介绍','The museum’s Italian collection includes Renaissance paintings, regional maps, and letters written in Italian.','博物馆的意大利藏品包括文艺复兴绘画、地区地图和用意大利语写的信件。','The museum’s Italian collection includes / Renaissance paintings / regional maps / and letters written in Italian.','Italian.s2 作形容词，表示意大利的、意大利人的或意大利语的。','该词修饰藏品，也出现在“用意大利语写的信件”中。')],mistakes:[M('The guide described a painting from Rome as Italian but claimed that Italian meant “from Ireland.”','The guide described the painting from Rome as Italian and explained its connection with Italy.','Italian 与意大利有关，不表示来自爱尔兰。')],quiz:[Q('Italian',1,1,'An Italian may be?','a person from Italy','a person from Iceland','a type of chemical isotope','a person from Italy','Italian.s1 可指意大利人。'),Q('Italian',2,1,'Italian can also refer to?','the Romance language spoken in Italy','the Germanic language spoken in Norway','a magazine edition','the Romance language spoken in Italy','Italian.s1 也指意大利语。'),Q('Italian',3,2,'Which phrase uses Italian as an adjective?','Italian architecture','an Italian who lives in Rome','she speaks Italian','Italian architecture','Italian architecture 中 Italian 修饰 architecture。','word-formation'),Q('Italian',4,2,'A dish described as Italian is associated with?','Italy or its culinary traditions','an island too small to map','irrevocable law','Italy or its culinary traditions','Italian 可表示与意大利及其文化相关。')]});
D('Italy',{etymology:E('Italy is the English name of the country in southern Europe; it also serves by metonymy for the country’s culture, cuisine, or national sports teams.','Italy'),contexts:[C('Italy.s1','旅行安排','The students traveled through Italy by train, stopping in Florence, Rome, and Naples.','学生们乘火车游历意大利，在佛罗伦萨、罗马和那不勒斯停留。','The students traveled through Italy by train / stopping in Florence / Rome / and Naples.','Italy.s1 指南欧国家意大利。','列举的城市都位于意大利，说明该词指国家。')],mistakes:[M('The itinerary described Italy as a country in northern Europe between Norway and Sweden.','The itinerary described Italy as a country in southern Europe, with Rome as its capital.','意大利位于南欧，并非挪威与瑞典之间。')],quiz:[Q('Italy',1,1,'Italy is a country in?','southern Europe','South America','the Arctic Ocean','southern Europe','Italy 是位于南欧的国家。'),Q('Italy',2,2,'A headline saying “Italy wins the final” may refer to?','the Italian national team','the country’s railway map','a small island off Greece','the Italian national team','Italy.s2 可用国家名代指国家队。'),Q('Italy',3,2,'“We ordered Italy for dinner” would most likely mean?','we ordered Italian food','we ordered the country itself','we bought an isotope','we ordered Italian food','Italy 可转指意大利文化或菜肴。'),Q('Italy',4,1,'Which city is in Italy?','Rome','Oslo','Lima','Rome','罗马是意大利首都。')]});
D('iterate',{etymology:E('Iterate comes from Latin iterare “to do again”; it means repeat an action or cycle, often through successive revisions.','iterate'),contexts:[C('iterate.s1','软件开发','The design team will iterate the checkout page after each round of user testing, changing one confusing step at a time.','设计团队将在每轮用户测试后迭代结账页面，每次只修改一个令人困惑的步骤。','The design team will iterate the checkout page / after each round of user testing / changing one confusing step / at a time.','iterate 指重复某过程，常通过多轮改进逐渐完善。','每轮测试后再修改并重试，形成迭代过程。')],mistakes:[M('The team said it iterated the prototype after building it once and never testing, revising, or repeating any step.','The team iterated the prototype through several rounds of testing and revision.','只做一次且不重复或修改，不属于迭代。')],quiz:[Q('iterate',1,1,'To iterate a design is to?','repeat and refine it through successive rounds','publish it once and never revisit it','turn it into an island','repeat and refine it through successive rounds','iterate 指通过反复进行来改进。'),Q('iterate',2,1,'Which team is iterating?','one that tests a draft, revises it, and tests again','one that accepts the first draft without review','one that deletes every record','one that tests a draft, revises it, and tests again','测试、修改、再测试构成迭代。'),Q('iterate',3,1,'The verb iterate is related to the idea of doing something?','again','invisibly','irresponsibly','again','iterate 来源含“重复做”的意思。','word-formation'),Q('iterate',4,1,'A software team may iterate to?','improve a feature in repeated cycles','avoid all user feedback','make its release irrevocable','improve a feature in repeated cycles','多轮改进可使软件功能逐步完善。')]});
D('itinerant',{etymology:E('Itinerant comes from Latin itinerari “to travel,” from iter “journey”; it describes a person or job that moves from place to place.','itinerant'),contexts:[C('itinerant.s1','乡村医疗','An itinerant nurse visits several remote villages each week rather than working at one permanent clinic.','一名巡回护士每周探访多个偏远村庄，而不是在固定诊所工作。','An itinerant nurse visits several remote villages each week / rather than working / at one permanent clinic.','itinerant.s1 作形容词，描述流动巡回、不断变换地点的工作或生活方式。','护士在不同村庄之间巡回服务。')],mistakes:[M('The nurse was itinerant because she worked in the same clinic every day for thirty years without traveling.','The nurse was itinerant because her work took her from village to village.','长期固定在同一诊所工作与 itinerant 的流动性相反。')],quiz:[Q('itinerant',1,1,'An itinerant worker?','moves from place to place','stays in one permanent office','issues a magazine every month','moves from place to place','itinerant.s1 指巡回流动的。'),Q('itinerant',2,2,'An itinerant may be?','a traveling worker','a fixed location','an isotope','a traveling worker','itinerant.s2 可作名词指巡回者。'),Q('itinerant',3,1,'Which job is most likely itinerant?','a clinician who visits several rural towns','a clerk assigned permanently to one desk','a guard who never leaves one gate','a clinician who visits several rural towns','在多个城镇间提供服务是巡回工作。'),Q('itinerant',4,1,'Itinerant is closest to?','traveling','irrevocable','irritable','traveling','traveling 可表达不断移动的特征。','confusable')]});
D('itinerary',{etymology:E('Itinerary comes from Late Latin itinerarium, a record or description of a journey; it can mean a travel plan or the route actually traveled.','itinerary'),contexts:[C('itinerary.s1','旅行协调','The itinerary lists the ferry departure, two museum visits, and the hotel check-in time for each day.','行程表列出了每天的渡轮出发时间、两次博物馆参观和酒店入住时间。','The itinerary lists / the ferry departure / two museum visits / and the hotel check-in time for each day.','itinerary.s1 指详细的旅行计划或日程安排。','行程表按天列出交通、参观和住宿安排。')],mistakes:[M('The itinerary was complete even though it gave no dates, destinations, route, or schedule for the trip.','The itinerary was complete because it listed the destinations, transport, and daily schedule.','缺少行程所需的目的地和安排，不能称为完整行程表。')],quiz:[Q('itinerary',1,1,'A travel itinerary is?','a detailed plan or schedule for a trip','a list of a magazine’s articles','a legal order that cannot be revoked','a detailed plan or schedule for a trip','itinerary.s1 指旅行计划和日程。'),Q('itinerary',2,2,'The itinerary of a long expedition can mean?','the route the travelers followed','the travelers’ lunch bill','the isotope ratio of a sample','the route the travelers followed','itinerary.s2 可指实际走过的路线。'),Q('itinerary',3,1,'Which item belongs in a travel itinerary?','the train departure time and hotel check-in','a private medical history unrelated to travel','a list of ironwork repairs','the train departure time and hotel check-in','交通与入住时间是行程安排内容。'),Q('itinerary',4,1,'An itinerary helps travelers know?','where they will go and when','which laws are irrevocable','how to irritate a person','where they will go and when','行程表帮助旅客了解目的地和时间安排。')]});
D('jade',{etymology:E('Jade entered English through French from Spanish piedra de ijada, “stone of the flank,” because it was once used as a remedy for kidney pain; it names a valued ornamental stone and can also mean tire or weary.','jade'),contexts:[C('jade.s1','工艺鉴赏','The carver chose a pale-green piece of jade for the pendant because its fine grain could hold delicate details.','雕刻师为吊坠挑选了一块浅绿色玉石，因为细腻的质地适合刻画精致细节。','The carver chose a pale-green piece of jade / for the pendant / because its fine grain / could hold delicate details.','jade.s1 指通常呈绿色、质地坚硬、可用于装饰和雕刻的玉石。','玉石的细腻质地适合制作吊坠。')],mistakes:[M('The jeweler called the soft plastic bead jade even though it scratched easily and contained no ornamental stone.','The jeweler called the hard green stone jade and carved it for a pendant.','易刮伤的塑料珠不是玉石。')],quiz:[Q('jade',1,1,'Jade is valued as?','a hard ornamental stone','a form of irrigation','a legal issue','a hard ornamental stone','jade.s1 指用于装饰的玉石。'),Q('jade',2,2,'To jade someone is to?','tire them until they lose interest or energy','give them an ornamental stone','make a permit irrevocable','tire them until they lose interest or energy','jade.s2 作动词可表示使疲倦或厌倦。'),Q('jade',3,1,'Which object is made from jade?','a carved green-stone pendant','a paper itinerary','a radio ionosphere','a carved green-stone pendant','玉石可雕刻成吊坠。'),Q('jade',4,2,'A long, repetitive task may jade a worker by?','wearing down the worker’s energy and interest','making the worker an islander','changing the task into an isotope','wearing down the worker’s energy and interest','反复任务可能让人疲惫厌倦。')]});
D('jagged',{etymology:E('Jagged is formed from jag, a sharp notch or projection, with -ed; it describes an edge or outline with rough, irregular points.','jagged'),contexts:[C('jagged.s1','地貌描写','A jagged ridge cut across the horizon, its sharp peaks outlined against the pale evening sky.','一道嶙峋的山脊横贯地平线，尖锐的峰峦映在浅色的傍晚天空中。','A jagged ridge cut across the horizon / its sharp peaks outlined / against the pale evening sky.','jagged 描述边缘粗糙、带有尖锐不规则突起的形状。','山脊轮廓由参差尖峰组成。')],mistakes:[M('The glass broke into a jagged edge that was perfectly smooth, rounded, and free of sharp points.','The glass broke into a jagged edge with rough, sharp points.','完全平滑圆钝的边缘不能称为 jagged。')],quiz:[Q('jagged',1,1,'A jagged edge is?','rough and marked by sharp irregular points','smooth and perfectly rounded','soft and invisible','rough and marked by sharp irregular points','jagged 指参差不齐、带尖角的。'),Q('jagged',2,1,'Which outline is jagged?','a mountain ridge with uneven sharp peaks','a perfect circle drawn with a compass','a straight line with no bumps','a mountain ridge with uneven sharp peaks','尖锐参差的山峰构成 jagged 轮廓。'),Q('jagged',3,1,'Jagged is closest to?','rough-edged','iridescent','irrevocable','rough-edged','rough-edged 同样描述边缘粗糙不齐。','confusable'),Q('jagged',4,1,'A broken bottle should be handled carefully because its glass may be?','jagged','irritable','itinerant','jagged','碎玻璃可能有尖锐不规则边缘。')]});
D('jailer',{etymology:E('Jailer is formed from jail with the agent suffix -er and names a person who guards prisoners and keeps them in custody.','jailer'),contexts:[C('jailer.s1','监狱生活','The jailer checked the cell doors at midnight and recorded that every lock was secure.','监狱看守在午夜检查牢房门，并记录所有锁具均已锁好。','The jailer checked the cell doors / at midnight / and recorded / that every lock was secure.','jailer 指负责看守囚犯并确保其被拘押的人。','检查牢门和锁具是看守职责。')],mistakes:[M('The newspaper called the defense attorney the jailer even though she represented the prisoner and had no custody duties.','The newspaper called the officer who guarded the prisoner the jailer.','代表囚犯的律师不负责看守或拘押。')],quiz:[Q('jailer',1,1,'A jailer is responsible for?','guarding prisoners in custody','designing a travel itinerary','testing an isotope','guarding prisoners in custody','jailer 指监狱看守。'),Q('jailer',2,1,'Who is most likely to check cell locks at night?','a jailer','an islander','an investor','a jailer','检查牢门是监狱看守的职责。'),Q('jailer',3,1,'Jailer is formed from jail plus?','-er','-ity','-ous','-er','-er 表示执行相关工作的人。','word-formation'),Q('jailer',4,1,'A jailer differs from a defense lawyer because the jailer?','guards prisoners rather than representing them in court','argues the prisoner’s legal case','writes a magazine issue','guards prisoners rather than representing them in court','看守负责羁押安全，律师负责法律辩护。','distinction')]});
D('janitor',{etymology:E('Janitor comes from Latin ianitor “doorkeeper,” from ianua “door”; in modern English it commonly names a caretaker who cleans and maintains a building.','janitor'),contexts:[C('janitor.s1','校园管理','The janitor cleaned the science rooms after class and repaired a loose handle on the laboratory door.','放学后，学校管理员打扫了科学教室，还修好了实验室门上松动的把手。','The janitor cleaned the science rooms after class / and repaired a loose handle / on the laboratory door.','janitor 在现代英语中常指负责清洁和日常维护楼宇的管理员。','打扫教室并维修门把手属于楼宇维护工作。')],mistakes:[M('The school called the visiting parent the janitor because she toured the building once, although she did not clean or maintain it.','The school called the employee who cleaned and maintained the building the janitor.','偶尔参观的访客不承担楼宇清洁维护职责。')],quiz:[Q('janitor',1,1,'A janitor usually?','cleans and helps maintain a building','writes the building’s travel itinerary','issues an irrevocable contract','cleans and helps maintain a building','janitor 常指清洁和维护楼宇的管理员。'),Q('janitor',2,1,'Which task belongs to a janitor?','mopping a school hallway and fixing a loose door handle','investigating a court case','measuring carbon isotopes','mopping a school hallway and fixing a loose door handle','清扫走廊和简单维修属于管理员工作。'),Q('janitor',3,1,'The older root of janitor referred to a?','doorkeeper','metal alloy','small island','doorkeeper','janitor 源自拉丁语“看门人”。','word-formation'),Q('janitor',4,1,'A janitor differs from a visitor because the janitor?','has ongoing cleaning or maintenance duties','enters the building only once','buys an invoice','has ongoing cleaning or maintenance duties','管理员有持续的清洁或维护职责。','distinction')]});

})();
